window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_055"]={"n":"张元凯","dyn":"明","poems":[{"t":"杂诗二十首 其一","f":"五言古诗","c":["时序有代谢，晦朔若循环。","灵景歘以驰，六龙杳难攀。","舜华曜曦林，蜉蝣息夕寰。","流运感人思，履世云孔艰。","菌芝想霞外，孔翠悲笼间。","栖遁托素业，韬精保朱颜。","迅彼云螭驾，迟尔冥鸿还。","长揖当涂客，去矣归空山。"]},{"t":"杂诗二十首 其二","f":"五言古诗","c":["阊阖有高楼，岩岩临万雉。","财赋五都雄，声利三川侈。","千花含碧城，九衢回绿水。","拂云韶頀音，照地明光绮。","我世授一廛，蓬蒿吴趋里。","闭户岁月深，凉风日夕起。","驰光娱乐散，幻景繁华徙。","至哉物外游，超然忘所履。"]},{"t":"杂诗二十首 其三","f":"五言古诗","c":["大运若转毂，鸿钧回化光。","穷达须有命，顺时以行藏。","君子或豹变，大人或龙翔。","谁为鼓其机，所过神无方。","南箕下人间，帝命弼有商。","何知肖形者，宛在版筑傍。","济旱霈霖雨，调元摄阴阳。","乃识宇宙事，固吾分所当。"]},{"t":"杂诗二十首 其四","f":"五言古诗","c":["吾友好名士，居然抱明哲。","硕人赋考槃，圭组良不屑。","朝刈中原葵，暮采西山蕨。","陟岭高云旋，濯水空潭澈。","白璧不可为，宁以青蝇缺。","皎皎机上丝，岂同缁尘涅。","独有孤松树，苍姿照白雪。","异彼夭桃花，甘以色取悦。"]},{"t":"杂诗二十首 其五","f":"五言古诗","c":["毁誉不可校，荣悴安能期。","飘风逐浮云，恍惚万象移。","头白失塞马，衣文附灵牺。","不为智者虑，则为达士嗤。","名勋盖一世，世改人不知。","区区千金子，徒戒垂堂为。","矧乃草莽间，暂借鹪鹩枝。","得酒尽舒啸，短鬓春风吹。"]},{"t":"杂诗二十首 其六","f":"五言古诗","c":["天上白玉虹，延袤十万里。","昭回下紫溟，飞来跨瑶水。","仙人挟之游，飘飖靡所止。","祖骞寻河源，浮槎适孔迩。","长揖银汉间，相遗赤虬履。","乃饰双明珠，加缘五色绮。","提携未轻著，纳令授孙子。","千载俟风云，一附鸾鹤起。"]},{"t":"杂诗二十首 其七","f":"五言古诗","c":["英雄树大业，端倪莫可循。","出处更险夷，变化驱鬼神。","释来有莘野，投竿渭水滨。","潜龙岂久淹，跃渊始见鳞。","落落屠与钓，相继拥朱轮。","尺蠖具至理，其屈求以伸。","蠛蠓能飞扬，灵贵矧乃人。","大禹惜寸晷，分阴当自珍。"]},{"t":"杂诗二十首 其八","f":"五言古诗","c":["楚人云千金，不如布一诺。","由也以片言，折狱良不错。","忠谅在人耳，隐然闻谔谔。","对谈恒借躯，万乘遗如屩。","所以国诸侯，不负布衣约。","意气吐白虹，千寻走寥廓。","今人徒嚣嚣，此道委沟壑。","仲连宁蹈海，岂独秦风薄。"]},{"t":"杂诗二十首 其九","f":"五言古诗","c":["凉风起昨夜，大火忽西移。","蟋蟀啼近床，流萤飞入帷。","白发竟盈把，丹砂尚无期。","朝散陆贾金，暮披张衡诗。","四愁郁不开，万金亦奚为。","叹息竟无语，俛视川波驰。","孤怀易成感，失路多所疑。","朝绯犹可典，日日倾芳卮。"]},{"t":"杂诗二十首 其十","f":"五言古诗","c":["屏居卧南冈，策杖遵行苇。","凉风吹絺衣，澄江澹生朏。","纵睇秋旻高，云英何韡韡。","感时鸣蟋蟀，阅世遗葑菲。","鹤岂愿乘轩，龟且聊曳尾。","侘傺辞帝阍，偃蹇伴山鬼。","庞公荷耒耜，君平谢筐篚。","白首抱明德，斯人岂不伟。"]},{"t":"杂诗二十首 其十一","f":"五言古诗","c":["玄霜凋碧草，熙阳媚红芳。","地道顺天施，不违物理常。","蛾眉对尊酒，螓首临镜光。","綵树栖鸑鷟，绿波荡鸳鸯。","荣华销逝景，娱乐安久长。","南山孤生柏，结根丹崖傍。","贞干回造化，叶叶生馨香。","愿借黄鹄翼，与之同颉颃。"]},{"t":"杂诗二十首 其十二","f":"五言古诗","c":["朝为清庙诗，暮作明堂赋。","赋剪秋空云，诗濯锦江露。","织成文绮霞，挂在珊瑚树。","声价比南金，光耀掩大璐。","缄之赠所知，无媒得君路。","从兹失颜色，飒如枯蓬暮。","遂令弃中衢，咄嗟谁复顾。","杨意若可逢，薄言一往愬。"]},{"t":"杂诗二十首 其十三","f":"五言古诗","c":["仙人佳何许，迢迢白玉京。","弱水悬碧海，赤城凌太清。","昨遇壶中公，引我接容成。","倒著苍凫舄，横吹紫鸾笙。","泠然饮一勺，丹液融金茎。","手拈赠三花，回车下蓬瀛。","归来见乡井，偪促还自惊。","招邀向时鹤，跨蹑游八纮。"]},{"t":"杂诗二十首 其十四","f":"五言古诗","c":["灼灼芙蓉花，开在秋江侧。","彷佛临镜妆，嫣然好颜色。","美人日暮来，搴裳娇无力。","甫采聊自佩，再采还自匿。","欲以寄远人，明我长相忆。","浮云天外驰，长江限南北。","搔首无一语，仰看双飞翼。","踟蹰怯独归，烟水微茫黑。"]},{"t":"杂诗二十首 其十五","f":"五言古诗","c":["结发慕遐躅，息驾怀幽奇。","去来山林客，寤寐濠梁期。","岸沙皓明灭，陂冈郁参差。","坐弄霞上月，载采岩下葵。","野酌草昧中，素襟松风披。","蹈海鲁仲连，逃山介子推。","遗荣终自爱，任智亦何为。","向来冥寂意，唯有孤云知。"]},{"t":"杂诗二十首 其十六","f":"五言古诗","c":["有士客长安，三冬有旨蓄。","射策苦不收，归来卧空谷。","对我长歔欷，悲风生林木。","未得平津延，已见咸阳逐。","一言足取相，奚必三千牍。","无歌可指凤，有赋元因鵩。","徬徨亦何为，唯共穷途哭。","展也诗人言，蔌蔌方有谷。"]},{"t":"杂诗二十首 其十七","f":"五言古诗","c":["雨散无聚时，河奔无还流。","岁月不我与，逝矣难再留。","隙驹真促景，富贵焉可求。","欲追凌风翮，云中无轻舟。","卫霍甫青鬓，功业等山丘。","广也七十战，白首不得侯。","成固由天幸，败亦匪人谋。","嗟嗟惜日短，秖为达士羞。"]},{"t":"杂诗二十首 其十八","f":"五言古诗","c":["吾祖产濠梁，偶成风云会。","潜壑攀飞龙，薄海生霖霈。","底定锡大封，骠骑功居最。","桓桓镇南国，天子赐旌旆。","祇受不世赏，山河元砺带。","本从代邸功，汗马同丰沛。","瓜瓞延秦吴，两地滥冠盖。","茕茕余小子，岁月微禄赖。"]},{"t":"杂诗二十首 其十九","f":"五言古诗","c":["东海有佳人，矫矫云中姿。","回翔自千仞，翻然斯来仪。","光彩照四极，声华驰九夷。","凤凰世希有，众人乃见疑。","归巢弇山颠，孤踪蓬瀛期。","曰余久沉冥，附翼惊以嬉。","遗我绿绮琴，饮我白玉卮。","卮酒良取醉，琴调罕所知。"]},{"t":"杂诗二十首 其二十","f":"五言古诗","c":["冥鹄耻淹栖，良驷喜超轶。","出门聊顾盼，岁月真如失。","春阳丽其晖，秋霜凄以瑟。","俯仰二十年，浮沈如一日。","贞士黄口谗，淑女蛾眉嫉。","甫动季鹰思，再被展禽黜。","苔绣芙蓉匣，雀罗蓬蒿室。","所有金仆姑，已换银不律。"]},{"t":"览古诗十首 其一","f":"五言古诗","c":["弱冠厌经学，夙抱四方志。","慷慨少年场，游谈古人事。","列国称豪雄，翩翩公子四。","并负绝世资，矧藉王公位。","而何多穷交，不弃抱关吏。","揽辔骄顾盼，抱剑同寝寐。","筹画总若神，肝胆良可视。","踊跃赴人急，汤火敢言避。","斯人忽千秋，末由一附骥。","结客固有心，食贫乃憔悴。"]},{"t":"览古诗十首 其二","f":"五言古诗","c":["邯郸得和璧，居然启秦衅。","宦者荐舍人，持献蹈白刃。","却立竟不前，睨柱久不瞬。","彼负连城约，我以空手进。","明月藏在怀，飘风归何迅。","崤函百万师，敢夺匹夫信。","始著章台名，终善渑池傧。","鼓瑟不能辞，击缶强相引。","一人气奋扬，一国威自振。","犬子成都生，矢心良慕蕳。"]},{"t":"览古诗十首 其三","f":"五言古诗","c":["主罕能知人，士实感知己。","所以古豫让，报仇良不止。","一入涂厕中，再出隐桥涘。","漆身若被绣，吞炭若飨簋。","大义激其仇，仇衣惠然褫。","所为虽极难，所志在必死。","死者已无后，死亦何为尔。","烈士固有心，存乎上所使。","傥彼筮仕初，即遇以国士。","将报智伯者，而报中行氏。"]},{"t":"览古诗十首 其四","f":"五言古诗","c":["秦人谋席卷，六国俱吞声。","季子起闾阎，鼓舌能倾城。","揣摩天下事，了若指掌明。","连亲从自合，投隙离其衡。","廿载函谷关，晏然无甲兵。","计画良亦伟，权变业已行。","惜哉侈金多，所至令人轻。","卒被反间死，夙昔空营营。","不肯帝秦者，齐有鲁先生。","功成不受赏，千载多令名。"]},{"t":"览古诗十首 其五","f":"五言古诗","c":["九月旅燕京，清霜飞马鞍。","偶与酒人游，因思太子丹。","屡避田生席，日奉荆卿餐。","缟衣送将远，变徵声无欢。","委肉饿虎蹊，燎毛洪炉端。","吁嗟徐夫人，不落秦王冠。","遂令易水上，千古悲风寒。","先朝欲报仇，临菑终见残。","今日图雪耻，智虑亦已殚。","强暴适天幸，壮士摧心肝。"]},{"t":"览古诗十首 其六","f":"五言古诗","c":["达节圣所贵，止足愚罔图。","历观功名士，负乘摧中途。","独慕文成侯，始终与道俱。","沛中殆天授，圮上非神乎。","扶汉汉已王，仇秦秦已无。","白首未言迈，赤松以为徙。","于此犹人间，忍见良弓枯。","晚岁招四皓，羽翼聊代吾。","出处何从容，千载称为儒。","西京谁继躅，贤哉二大夫。"]},{"t":"览古诗十首 其七","f":"五言古诗","c":["大朴日已漓，小智恒自伐。","汉廷功名士，石奋能超越。","醇谨本少文，中涓受书谒。","洵美一家让，万石供岁月。","建归入子舍，忘已垂白发。","庆误坐车中，乃甘肉袒罚。","马尾数何勤，中裙浣无歇。","抱拙竟奚为，履道罔有缺。","眷焉简帝心，尊宠独昭揭。","功高信越辈，骄矜中道蹶。"]},{"t":"览古诗十首 其八","f":"五言古诗","c":["汉家击匈奴，调发不停轨。","战骨窴颜山，流血疏勒水。","度幕愁单于，奏凯喜天子。","茅土锡有功，丹书曜连玺。","独惜飞将军，无能建尺咫。","白首失期会，塞下饮恨死。","遗腹有门风，吁嗟輮戎垒。","军败鼓不鸣，空拳何能耳。","期展曹柯盟，竟作莫敖祀。","彼苍良不仁，祖孙厄如此。"]},{"t":"览古诗十首 其九","f":"五言古诗","c":["古之饮者流，沉冥自夷旷。","迈迹隘区中，逸情出云上。","如何灌仲孺，骂坐日怏怏。","丞相生贵甚，杯酒深责望。","魏其失势人，安能保无恙。","块垒浇不开，颍水翻浊浪。","嗟嗟老秃翁，举止竟踉蹡。","我亦事曲蘖，尚论独惆怅。","达生贵忘机，韬精齐得丧。","愿从竹林游，颓然且酣畅。"]},{"t":"览古诗十首 其十","f":"五言古诗","c":["生长夫差城，里有翁子宅。","翁子少也贱，落魄无推择。","长镵持且负，短歌行自适。","骨肉弃中涂，遑遑欲头白。","将军西入关，富贵颇相迫。","微露会稽印，惊散守邸客。","衣绣归故乡，颜色非畴昔。","有司所治道，是常卖薪陌。","乃知被褐人，恒自怀和璧。","贤豪在人间，岂以困穷厄。"]},{"t":"杂拟诗六首 其一","f":"五言古诗","c":["少小结游侠，长大慕豪英。","六郡已脱籍，三辅乃有声。","藏活以百数，脱死常独行。","风沙扑马首，关月候鸡鸣。","将军言郭解，公子拜侯嬴。","彼非有一命，权可当专城。","所以奇节士，慷慨说捐生。","大笑东家儿，杀人隐姓名。"]},{"t":"杂拟诗六首 其二","f":"五言古诗","c":["东都多妖丽，住近春明门。","单车来侠客，驷马回王孙。","妆成耀皎日，结佩鸣瑶璠。","举止有飞态，流目无定源。","金尊浸圆月，绮被绣双鸳。","色笑延新宠，肝胆怀旧恩。","团扇总含悲，前鱼羞自言。","容华易零落，抚枕忧心烦。"]},{"t":"杂拟诗六首 其三","f":"五言古诗","c":["有客住吴国，赠我以莫耶。","提携未出匣，随手生霜花。","或恐是神物，吞吐虹光斜。","不惜黄金装，横在白鼻騧。","边烽昨夜至，飞符度流沙。","秋月照长城，边骑纷如麻。","按剑左右盼，目已无浑邪。","丈夫为天下，安能复顾家。"]},{"t":"杂拟诗六首 其四","f":"五言古诗","c":["去年秋未半，良人去庭闱。","今年秋欲尽，关塞音书稀。","尘生在御瑟，苔绿当窗机。","凉风动蘼芜，阴阴吹罗帷。","白云疾飞来，掩我明月晖。","空房怯不进，独坐长歔欷。","县家羽檄至，沙场新解围。","但求免锋镝，何敢望旋归。"]},{"t":"杂拟诗六首 其五","f":"五言古诗","c":["有士卧蓬蒿，悽怆恒鲜欢。","饥乌噪檐侧，哀猿号树端。","玄云被旭日，下土流光寒。","昨夜严霜飞，林中木叶乾。","凋彼萧与藿，曷以供朝餐。","苟无邓通钱，莫弹贡禹冠。","锻羽如栖鸡，努力空伐檀。","一经令人老，竖儒安足叹。"]},{"t":"杂拟诗六首 其六","f":"五言古诗","c":["海深犹可测，河广犹可凭。","狂夫如飘风，心志莫可惩。","结发明信誓，中道忽侵凌。","葑菲槩尔遗，荼蓼茹谁憎。","新宠良自固，故欢难再仍。","凉飙起霜夕，陨叶何棱棱。","羞以孤帷搴，坐见圆月升。","三复白华诗，伤哉人无恒。"]},{"t":"春游篇二首 其一","f":"五言古诗","c":["芬芳蔼京邑，太和盈宇宙。","如何惬赏心，矧复值春候。","柔荑偃条风，嘉树郁灵囿。","川上悦于飞，山梁闻朝雊。","舆台被文绮，女郎飘长袖。","车马何怒鲜，游閒日驰骤。","陈遵驱藩车，爰丝通中冓。","愿言绿酒醑，无事黄金寿。"]},{"t":"春游篇二首 其二","f":"五言古诗","c":["晨出东都门，曙旭散城阙。","春莺巧如簧，春草绿如发。","韶岁当令辰，丹葩耀林樾。","鸣镳事遨游，万里轻秦越。","怀璧照十乘，佩珠悬明月。","无端有近亲，叵测通私谒。","琴瑟临邛携，金钱馆陶发。","今时不娱乐，容华坐消歇。"]},{"t":"苦热诗四首 其一","f":"五言古诗","c":["炎暑惟兹夏，我思鹿门叟。","脱屣疏流泉，不栉开山牖。","阴阴树成幄，习习风生肘。","与妇并荷锄，所耕亦计口。","解衣憩南冈，相馌持斗酒。","曲肱听鸣蝉，初月升高柳。","地岂避秦来，身非为汉有。","挥汗自成浆，弹冠与结绶。"]},{"t":"苦热诗四首 其二","f":"五言古诗","c":["炎暑惟兹夏，我思富春濑。","空山无结构，高树俨倾盖。","匡坐理钓丝，澄江流夕霭。","纤鳞或浮沉，漪藻回如带。","浚谷归白云，高天零沆瀣。","烦虑息区中，定灵想霞外。","五月披羊裘，亢阳生爽籁。","寄语谢故人，轩冕安足赖。"]},{"t":"苦热诗四首 其三","f":"五言古诗","c":["炎暑惟兹夏，我思竹林士。","岸帻绿云浮，拂袖寒商起。","层阴下遥岑，朱曦逝清沚。","设礼岂为吾，迕俗元忘尔。","深杯映明月，素琴澹流水。","冥寂契无为，沈酣良有以。","歌凤睨当途，犹龙伏柱史。","旷哉兹数贤，芳声共千祀。"]},{"t":"苦热诗四首 其四","f":"五言古诗","c":["炎暑惟兹夏，我思东山墅。","高台凌飞霞，华馆荫修渚。","坐隐澹忘归，谈玄自容与。","玉树垂盈庭，幽兰被孤屿。","翩翩曳轻绡，临风欲仙举。","更倚如花妓，含笑进绿醑。","凉飔生高梧，灵凤斯爰处。","愿言终远志，浮云任来去。"]},{"t":"杂咏十首 其一 渔父","f":"五言古诗","c":["溪桥转山径，湖水碧于苔。","渔舟柳阴下，举网得四腮。","樵薪犹未至，新醅业已开。","团圞坐妻孥，不簪亦不鞋。","欲要采菱人，西风吹船回。","蔌蔌芦叶响，月上潮正来。","波涛非云险，梦寐良不乖。","向逢楚大夫，言言伤我怀。"]},{"t":"杂咏十首 其二 樵父","f":"五言古诗","c":["偃树春不起，繁条秋弥丛。","长镵入空谷，历历摧枯蓬。","形骸肖山鬼，趫捷轻狙公。","玄熊夕相避，猛虎昼不逢。","素履往无咎，险阻穷能通。","有时不归来，高卧山之东。","积薪拟待价，沽酒明月中。","桎梏轩冕者，终焉愧此翁。"]},{"t":"杂咏十首 其三 学稼","f":"五言古诗","c":["滋兰徒佩芳，种菊徒采英。","饘粥苟不继，不如学躬耕。","荷锄出东皋，布谷方有声。","好雨以时至，春水昨夜生。","井井畎亩界，油油禾黍平。","吾志在一饱，匪冀仓箱盈。","南阳迟诸葛，谷口寻子真。","翻嫌沮溺辈，后世知其名。"]},{"t":"杂咏十首 其四 学圃","f":"五言古诗","c":["芍药恣欢谑，桃李竞光华。","吾本葵藿士，弃之等尘沙。","负郭开三径，言树桑与麻。","兼之艺蔬韭，春雨生萌芽。","接竹引寒泉，薙草驱鸣蛙。","绕畦白水流，傍屋青山斜。","浊酒聊自慰，劳力何须嗟。","终作灌园人，且卖故侯瓜。"]},{"t":"杂咏十首 其五 估客","f":"五言古诗","c":["积富匪用拙，良贾久居奇。","或遗戎王利，或挟寡妇赀。","艑舸江湖间，辎车都会驰。","居陶为朱公，适齐为子皮。","但知素封贵，不识县官谁。","蹑履明珠缘，揄袂文縠垂。","行乐谅无尽，金多任所之。","安能守穷巷，季次原宪为。"]},{"t":"杂咏十首 其六 侠客","f":"五言古诗","c":["背公死党客，朱家郭解伦。","布衣相雄长，闾里岂沉沦。","所至比敌国，所谋类鬼神。","空室生青草，半夜回朱轮。","走死地如骛，藏活士匪亲。","一诺成泰岱，千金化纤尘。","权可移卿相，貌不如中人。","犹闻侠骨香，千年事若新。"]},{"t":"杂咏十首 其七 射雉","f":"五言古诗","c":["有鷕两雉鸣，彩彩好羽仪。","挟弹东邻子，潜睨如蹲狸。","一发得其雄，再发并其雌。","洒血平芜间，赳赳过水湄。","微物不充鼎，凭高一扬眉。","结束驰前山，射杀子母麋。","丈夫飞食肉，肯饱藿与葵。","所志猎沙场，好生亦何为。"]},{"t":"杂咏十首 其八 射虎","f":"五言古诗","c":["李广不得志，屏居蓝田间。","大荒久尘埃，猿臂日閒閒，高秋偶会猎，白额藏草菅。","咆哮应弦倒，单车负以还。","烹之侑斗酒，鞟也何斑斑。","卒史北平来，为言兵入关。","天子思飞将，趣装出南山。","此时灞陵尉，已醒多愁颜。"]},{"t":"杂咏十首 其九 牧牛","f":"五言古诗","c":["春日喜载阳，原隰绿草稠。","牧子驱其群，迟回上高丘。","乱入苦竹冈，降饮浅水洲。","相聚不相触，众耳湿湿柔。","犉者洁可怜，骑之前村游。","睡来吹芦管，饥则饭乾糇。","老牯道傍喘，主人见且忧。","此是丞相责，莫漫箠苍头。"]},{"t":"杂咏十首 其十 牧豕","f":"五言古诗","c":["公孙牧豕时，种种已华颠。","伟身著短衣，昂首持长鞭。","涂附困泥中，白蹢涉菑田。","野乌饥萃止，辨色俱尚玄。","穷年逐什一，形秽莫可捐。","忽乘风云会，光华遍九天。","群豕化神龙，洿池变灵渊。","丈夫此身在，何愁屯与邅。"]},{"t":"闺词十二首 其一","f":"五言律诗","c":["昨日书到家，知君在天涯。","问妾近颜色，为报如荷花。","君若归来易，荷花露下媚。","君若归来难，荷花霜后残。"]},{"t":"闺词十二首 其二","f":"五言律诗","c":["捣衣声不乱，捣衣情自深。","秋风一夕起，闺中同此音。","妾捣君不闻，天涯自有砧。","也应如妾捣，为妾捣君心。"]},{"t":"闺词十二首 其三","f":"五言律诗","c":["去年折柳条，送君木兰桡。","今年折柳条，泪尽万里桥。","何时守故土，双栖学鹪鹩。","同见柳华盛，同见柳叶凋。"]},{"t":"闺词十二首 其四","f":"五言律诗","c":["忆昔初嫁君，明珠照绿云。","今日君离别，飞蓬乱不结。","忘我久食贫，游赵复游秦。","秦人未逐客，安能返乡国。"]},{"t":"闺词十二首 其五","f":"五言律诗","c":["思君劳梦寐，梦君归故园。","俨然乘驷马，衣上绣双鹓。","容华异昔日，冠盖盈前轩。","觉来心独喜，起对高堂言。"]},{"t":"闺词十二首 其六","f":"五言律诗","c":["琴瑟昔在御，莫不静而好。","自君久别离，房栊生青草。","弹琴无知音，调瑟多苦心。","弦繁曲亦乱，月落花阴阴。"]},{"t":"闺词十二首 其七","f":"五言律诗","c":["临别牵人衣，紫骝门前嘶。","倏忽袂已分，紫骝嘶不闻。","去去踏芳草，相亲在远道。","坐叹容华妍，不如紫骝好。"]},{"t":"闺词十二首 其八","f":"五言律诗","c":["挟弹羽林儿，柳下睨黄鹂。","少妇倚高楼，望见遥止之。","止之匪心恻，毛羽纯金色。","愿言化为印，提携夫君侧。"]},{"t":"闺词十二首 其九","f":"五言律诗","c":["睡起揽鲛绡，无烦带步摇。","不言花意静，顾影燕情娇。","自分力不禁，恐负良人心。","功成拜边郡，何得双双临。"]},{"t":"闺词十二首 其十","f":"五言律诗","c":["谁家采桑女，妖艳妆何靓。","贪看鸳鸯飞，立与桃花并。","柔条多远扬，钩乱如鸦鬓。","倾筐弃道傍，归照匣中镜。"]},{"t":"闺词十二首 其十一","f":"五言律诗","c":["夫婿乍封侯，尚尔玉关游。","欲绣一端锦，寄耀千貔貅。","行褰池上柳，芙蕖摘纤手。","颜色比不差，衔在天吴口。"]},{"t":"闺词十二首 其十二","f":"五言律诗","c":["皓魄不常圆，一月圆一夕。","明夕倏已亏，天道无停息。","人事徒可怜。","一亏不复圆。","娟娟芙蓉花，弃置秋江边。"]},{"t":"边词十二首 其一","f":"五言律诗","c":["大将屯云中，日见贼兵却。","天子玺书至，报功良不薄。","春风杨柳营，丝竹莲花幕。","军前上万寿，三举黄金爵。"]},{"t":"边词十二首 其二","f":"五言律诗","c":["结束良家子，翩翩居帐下。","从军不数年，节钺安可假。","耻随五校后，单骑走朔野。","龙剑跃且鸣，夺得追风马。"]},{"t":"边词十二首 其三","f":"五言律诗","c":["匈奴约和亲，边烽昼不举。","士卒渐忘战，军中罢超距。","盘跚弄婴儿，拍手学蛮语。","草间骑羝羊，引弓射鸟鼠。"]},{"t":"边词十二首 其四","f":"五言律诗","c":["秋风试鸣镝，忽见孤飞雁。","一矢铩其羽，遥堕前山涧。","众谓南来鸟，足有帛书绾。","策马往视之，野火新烧栈。"]},{"t":"边词十二首 其五","f":"五言律诗","c":["九月未授衣，十月边霜凛。","士卒夜苦寒，独抱雕戈寝，欲诉霍嫖姚，无奈生贵甚。","穿域正蹋鞠，阳春生兽锦。"]},{"t":"边词十二首 其六","f":"五言律诗","c":["结发在边境，姓名匈奴识。","大小七十战，身若凌空翼。","幕府功不报，封侯无消息。","醉尉夜呵人，道傍行不得。"]},{"t":"边词十二首 其七","f":"五言律诗","c":["仗钺出雁门，踊跃万人靡。","为国敢顾家，誓众唯有死。","金鼓声不哗，旌旗色何起。","不系五单于，无颜见天子。"]},{"t":"边词十二首 其八","f":"五言律诗","c":["调遣备边兵，尺寸守汉法。","蹀躞桃花驹，熠熠芙蓉匣。","夜夜忆闺人，万里梦魂洽。","梦中曳罗襦，觉来寝金甲。"]},{"t":"边词十二首 其九","f":"五言律诗","c":["冬暮兵犯塞，调发羽书亟。","同云覆积雪，万马不辨色。","持糒一半冰，落日方传食。","从军多少年，安能头常黑。"]},{"t":"边词十二首 其十","f":"五言律诗","c":["驰驱事戎马，方略若神授。","所将固常选，所当良无负。","已获浑邪归，复斩居耆首。","尚方铸金印，竟挂谁之肘。"]},{"t":"边词十二首 其十一","f":"五言律诗","c":["久隶行伍间，尚在偏裨下。","寒霜生铁衣，秋风劲弓弝。","执鞭乃吾分，窘辱何须讶。","卫青亦人奴，敢遽辞笞骂。"]},{"t":"边词十二首 其十二","f":"五言律诗","c":["辽海戍十年，拜爵苦不早。","蒙茸卷征衣，春风吹远道。","少妇倚高楼，王孙踏芳草。","秖恐见时颜，不似别时好。"]},{"t":"安履山房赠舅氏启孙二首 其一","f":"五言古诗","c":["黄鹄恣冥翮，寒松挺贞干。","纵尔寡谐合，允为明哲叹。","舅氏甘隐沦，幽栖抱璀璨。","冒枕白云多，隐几青山乱。","岩扉暮霭浮，风树空音散。","流坎任所止，豕鹿聊为伴。","不苦扬雄吃，而爱长卿慢。","原阡竭心力，愚谷安昏旦。","翻嫌鹿门叟，累彼妻孥爨。"]},{"t":"安履山房赠舅氏启孙二首 其二","f":"五言古诗","c":["横塘度单舸，五湖净如缟。","山障疑无路，花曲潜通岛。","主人垫角巾，有类郭有道。","檐间下尘榻，盘中剥新枣。","夕照去庭柯，片月流青昊。","千仞览德辉，昭回振远抱。","尊酒不及乱，玄言自论讨。","道以沉寂超，人与烟霞老。","置我丘壑间，宛然似舅好。"]},{"t":"时命篇","f":"五言古诗","c":["岧峣郁峻岭，波澜翻巨川。","吁嗟客游子，梯航俱不前。","白日忽沦没，清霜飞幽燕。","夏屋叹权舆，幸舍悲迁延。","握玉竟难饱，尺桂讵易然。","风前骭不掩，雪上屦半穿。","欲仕无中人，欲耕无良田。","营营声利涂，轩轾豪雄权。","谁念牛衣士，涕泗鸡埘边。","仲尼道路傍，伯夷空山颠。","贫贱岂尽愚，富贵岂尽贤。","时命有顺逆，达节良自全。"]},{"t":"醉宿僧舍觉起言志","f":"五言古诗","c":["偶携绿玉壶，来借青莲座。","桃花对命觞，尽醉颓然卧。","春云夜不飞，覆被为我衣。","残月升高檐，照见白板扉。","萧然在僧舍，起立双树下。","顾影独徘徊，万感生清夜。","原生久悬鹑，买臣行负薪。","嗟嗟江海客，何蒙牖下尘。","人生贵适意，富贵何时至。","投湘不可为，乘桴非吾事。","吾已无黄金，安用求知音。","楚狂接舆者，庶几获我心。"]},{"t":"中秋四山诗 其一 玄墓山","f":"五言古诗","c":["攀跻匪巉峭，佳胜兹岩具。","偶偕良朋来，不负探奇趣。","秋迟冥鸿归，云向潜虬护。","朗月升高天，深林曷知暮。","五湖浩无际，千峰俨欲赴。","渐辨涧底星，遽失峦间雾。","波流缟练长，光动金银互。","缥缈生虚无，楼台已改故。","恍观大海潮，雪浪排空骛。","何必三神山，仙人始回顾。","遗世鲜与徒，孤踪应有遇。","旷哉古今心，莫以荣名误。"]},{"t":"中秋四山诗 其二 铜井山","f":"五言古诗","c":["晨弭南湖棹，暮蜡东山屐。","千级石磴遥，半岭行云逆。","佛宫才数椽，僧厨少四壁。","井馀蛟龙腥，阶唯鸟兽迹。","崩奔群壑会，居然走震泽。","皎月出层岩，窈窕穿树隙。","寥空澹而澄，逾高光逾白，一照析秋毫，万象呈圆魄。","浮屿俨欲飞，列宿如可摘。","峦竹多清音，巢鹘无卑翮。","箕踞藉落叶，长啸振孤石。","兹夕登兹山，彷佛藐姑射。"]},{"t":"中秋四山诗 其三 虎山桥","f":"五言古诗","c":["凭眺凌崇峻，周览极浩渺。","日落出古寺，秋旻见归鸟。","石梁百尺横，苍渚游龙矫。","两崖崩欲坠，五湖环且绕。","人家隔花源，孤亭构木杪。","坐久待明月，亭亭映翠筱。","既望升较迟，微亏光仍皎。","近浦何氤氲，远峰亦缥缈。","桓伊笛自幽，范蠡舟偏小。","零露瀼瀼华，明星渐以少。","何事杯行缓，夷犹俟清晓。","溪山总含情，宛然留谢朓。"]},{"t":"中秋四山诗 其四 灵岩寺","f":"五言古诗","c":["兹山吴之望，云是故宫址。","再为佛子庐，今亦莽荆枳。","仲秋岩壑清，日暮冈峦紫。","浮图自孤撑，断碣仍碍屣。","绳床悬石室，空庭蒙葛藟。","四山出重云，飒飒林飙起。","缺月深韬光，慧灯照棐几。","谈禅谢觞酌，空门远尘轨。","相与證无生，夷然忘所履。","寂寂此岩阿，昔被明光绮。","二井苔藓封，俱曾照西子。","慨念今古人，荣华若流水。"]},{"t":"辕驹叹","f":"五言古诗","c":["万物有荣瘁，修途多险虞。","枥上曾称骏，辕下反为驹。","哀鸣望顾盼，主人恩不殊。","不覂骐骥驾，乃与驽蹇俱。","流沙千万里，秋风苜蓿枯。","梦想燕然山，追逐大将符。","皮相亦何凭，骨立亦何图。","傥再赐鞭策，犹堪任驰驱。"]},{"t":"林鹤篇","f":"五言古诗","c":["晏坐寄玄览，感物生遐思。","有鹙在梁饱，有鹤在林饥。","所处虽倒置，鹤也安足悲。","逍遥寓空谷，还与丛桂期。","一鸣闻九天，其子能和之。","夕可饮沆瀣，晨可餐灵芝。","驭彼王子乔，白云同差池。","回视在梁者，龌龊亦奚为。"]},{"t":"采菱词","f":"五言古诗","c":["菱角何纤纤，菱叶何田田。","鸳鸯与鸂鶒，对对浮清川。","采菱白晰郎，荡桨后复前。","偶逢西家姝，隔浦来采莲。","娇容入花乱，素腕随荇牵。","要住语绸缪，风动裙带偏。","采采忘采角，但采叶在船。","赠我双莲子，庶几不空还。"]},{"t":"织锦曲","f":"五言古诗","c":["织锦置新机，当窗取石支。","今日织一丝，明日织一丝。","离居日閒閒，何为织迟迟。","良人隶材官，贾勇能搴旗。","微功上幕府，拜爵及春时。","春时好衣锦，此锦正相宜。","金紫色照耀，麒麟光陆离。","看君身上服，称妾心中期。"]},{"t":"三月三日","f":"五言古诗","c":["元已晴旭丽，吴趋土风嘉。","芳甸古茂苑，离宫昔馆娃。","良辰动水嬉，锦浪被清涯。","士女娇容服，顾影生光华。","绿帻吹参差，红袖拥琵琶。","濯濯春杨柳，灼灼夭桃华。","相谑竟何赠，芍药萌红芽。","少年扶醉归，青楼明月斜。"]},{"t":"山中迟客","f":"五言古诗","c":["朝暾散深谷，宿莽互氤氲。","松露犹缀珠，高霞自成文。","晞发凌青壁，嗽齿度碧濆。","忽见衣领上，英英生白云。","不负黄鹄期，眷言沧海君。","同心挂缨组，折简聊相闻。","东山迟安石，兰亭要右军。","远驾如惠然，清晖良可分。"]},{"t":"听春莺","f":"五言古诗","c":["黄鸟出幽谷，差池翔南枝。","春风鼓其舌，如奏竹与丝。","绵蛮杂繁调，睍睆多婉词。","于飞不肯只，顾影若有思。","良时不易至，好音难重期。","公子正邀欢，伫听自忘疲。","芳宴洵足耽，杯到安能辞。"]},{"t":"观朝雨","f":"五言古诗","c":["南楼望远道，春雨江上生。","既洒鳷鹊观，复集凤凰城。","散水幻圆影，添瀑作碎声。","丝丝元不断，蔼蔼一何轻。","宿雾暗洲渚，朝隮莽苍屏。","柳条郁如结，花露泫以盈。","美人期不来，愁绪逐浮萍。"]},{"t":"独游","f":"五言古诗","c":["晚出白云轩，来过青莲宇。","翩翩曳短裾，不挂尘中组。","原草生芳荑，飞花满桑土。","独鹤先我行，南山遥为主。","莞尔听鸣禽，不觉逢渔父。","共笑嵇生懒，好锻对环堵。","何如今日游，春风采兰杜。"]},{"t":"独酌","f":"五言古诗","c":["栖栖不得志，春到罕芳宴。","偶有一壶酒，独酌聊自遣。","公荣曷与焉，嗣宗无由见。","东风川上来，入林堕花片。","黄鸟乃有情，睍睆还相唁。","古人功名会，成败忽如霰。","何事龙门生，不立醉者传。"]},{"t":"桂树","f":"五言古诗","c":["桂树何苍苍，不生桃李园。","久滋颍川水，远托箕山根。","离立不成林，偃蹇何所援。","商山采芝叟，无端去乘轩。","楚皋佩兰者，不返湘江魂。","何如老此树，终焉绝尘喧。","小山空有招，白云竟无言。"]},{"t":"箕山","f":"五言古诗","c":["家住箕山下，来往唯白云。","若无巢许辈，此地谁为群。","茅茨蔽风雨，琴书辞俗氛。","庭前乔松树，徙倚忘夕曛。","段干过于避，介推何至焚。","良友将远适，安车与玄纁。","人各自有志，不遣北山文。"]},{"t":"越溪庄赠主人别驾","f":"五言古诗","c":["主人少游侠，五陵裘马人。","中岁徇寸禄，十年苦风尘。","不调归别业，依然旧松筠。","百株植墙下，二顷在湖滨。","绿水青山区，何减桃源津。","长者多论交，载酒无冬春。","我来住高斋，不栉亦不巾。","信宿恒忘归，常时如避秦。","子猷雅好客，安道复情亲。","不然兴已尽，何事独留宾。"]},{"t":"春日湖上","f":"五言古诗","c":["少岁慕荣名，中道叹维谷。","卓彼白发叟，招我紫芝曲。","匪直谢簪绂，兹乃脱羁束。","万事不挂念，一壶存所欲。","杏花前村开，春水五湖绿。","倚棹看凫鹥，纷披波间浴。","夕阳忽下岭，行云渺相续。","莞尔会心处，寤寐向谁告。","清夜梦故人，居然建牙纛。","容或酬彼志，吾且知吾足。"]},{"t":"夏日寒山寺旭公房竹下迟王生不来与刘生饮","f":"五言古诗","c":["野寺昼寂寥，独鹤当门屏。","阴阴古墙下，一片绿云冷。","夕照上高檐，空翠落潭影。","如何炎隆时，有此清凉境。","入林无所事，匡床据高枕。","不见子猷来，便与公荣饮。","远抱托长风，孤怀自耿耿。","心契静者因，迹向寒山并。","凤鸟负远期，蜉蝣悲促景。","百年几何时，日日须酩酊。"]},{"t":"圌山朱都尉过访留宿草堂中夜不寐情见乎词","f":"五言古诗","c":["有客江上来，柳下住双桨。","身白俨如瓠，巨口仍广颡。","相见懒长揖，落魄高阳党。","呼儿且沽酒，把臂坐草莽。","十年交自倾，片言心觉爽。","明霞四散飞，长庚独先朗。","蝙蝠扑檐间，熠耀行草上。","凉风西南来，剌剌枝头响。","下榻不能寐，空庭共頫仰。","慷慨醉中言，何时起李广。"]},{"t":"七月六日同王赡美曹子念饮豹孙书屋","f":"五言古诗","c":["大火忽西流，凉飔起江沚。","萧散据匡床，脱帽仍解履。","高梧障重檐，短墙瓜葛藟。","一室无数椽，长风吹万里。","彷佛坐阴崖，来接巢居子。","旋开竹里厨，言鲙河之鲤。","南阮本不饶，留客乃如此。","旷适林中赏，逾觉贫交美。","何事慕贵游，汗流恒竟趾。","所以蹈海人，弃之如敝屣。"]},{"t":"七月七日集周公瑕鉴止堂坐同谢尉徐生","f":"五言古诗","c":["公瑾雅好客，醇醪具芳宴。","正及牛女辰，嘉会拟霄汉。","风流推谢安，才情见徐干。","共有青山情，颇悦白衣宦。","雕俎一何繁，羽爵行无算。","绿藻锦鳞游，朱栏柳丝乱。","虽未列歌钟，清音起松畔。","仰见纤月来，同彼双星灿。","怅别经一年，留欢无两旦。","人生聚会难，感之发长叹。"]},{"t":"中秋初度有感二首乙亥 其一","f":"五言古诗","c":["华月升高檐，广除步靡靡。","百年几何时，繁忧徒萃止。","结发事远游，轨路多荆枳。","九折悲覆车，皇皇旋旧里。","犹存临邛壁，欲探于陵里。","苦竹善钩衣，扁石恒碍履。","雀角穿我巢，谷风漂我垒。","哀哀慈母傍，怨慕羞称子。","脱粟尚弗充，何言甘与旨。","值此劬劳辰，乃惊犬马齿。","四十无闻焉，云何不遄死。"]},{"t":"中秋初度有感二首乙亥 其二","f":"五言古诗","c":["遄死复何恨，頫仰若有牵。","陟岾履宿草，背养已十年。","高圹良可营，屡空徒迁延。","巢中有三雏，参差齐父肩。","无食又无衣，抱影各孑然。","久凋王生柏，未见原公阡。","何有禽庆约，期了向平缘。","咄咄计安出，有泪如流泉。","况乃鲜兄弟，焭焭殊可怜。","但苦严霜飞，何知华月圆。","泌水衡门下，且草子云玄。"]},{"t":"送何都尉之汀漳","f":"五言古诗","c":["何生少精悍，持已能不泄。","孙吴一万言，澜翻在其舌。","三谒明光宫，曾进治安说。","结束趋辕门，老将同为列。","班生笔已投，终军繻久裂。","量移守闽峤，鼓行向毒热。","封狐吐妖氛，长鲸喷晴雪。","海色多溟濛，将星独昭澈。","不然守乐土，何以见奇节。"]},{"t":"述怀寄高邮贾生","f":"五言古诗","c":["昔与子周旋，揽镜头俱黑。","今与子别离，鬓边丝堪织。","黄鹄畏网罗，紫燕悲伏枥。","自顾无蛾眉，众女空见嫉。","执戟杨子居，门卒梅生职。","迟回陟羊肠，踟蹰弃鸡肋。","徒步出北门，雨雪霏霏湿。","偶逢淮海人，问子近消息。","惆怅吊长沙，贾生在胸臆。"]},{"t":"送客之楚","f":"五言古诗","c":["草木黄且落，陂冈纵复横。","飒飒阴风吹，繁条折不鸣。","迢递暮山上，日没寒云生。","去鲁非其志，游梁竟无成。","栖栖何所之，言涉湘与衡。","还将送君泪，寄吊古屈平。"]},{"t":"志别","f":"五言古诗","c":["祖道一尊酒，凉风江上生。","枫林一叶丹，秋动千山声。","星离越溪水，雨散吴王城。","我昔游燕赵，居人送我行。","今我亦送客，酒尽泪欲倾。","乃知送我者，掩袂多至情。"]},{"t":"楼居二首 其一","f":"五言古诗","c":["仙人好楼居，吾亦厌卑处。","结构倚遥岑，鸿飞终远举。","樛木荫白日，流水萦苍渚。","何必凉风来，孤高自消暑。","空山正阒寂，蓬门迟支许。","云霞几席流，嗒然无一语。"]},{"t":"楼居二首 其二","f":"五言古诗","c":["余生不偶世，块处空山久。","木末出岑楼，青旻一挥手。","高云翳我裾，明月入我牖。","坐见松树阴，群然麋鹿走。","郑真谷口锄，梁鸿庑下臼。","外是无长物，留巾漉美酒。"]},{"t":"卧疾四首 其一","f":"五言律诗","c":["抱疴卧中园，掩关白日静。","坐见凋兰芳，秋风忽凄冷。","蹇蹇披羊裘，徙倚望前岭。","为爱孤松枝，时时逗云影。"]},{"t":"卧疾四首 其二","f":"五言律诗","c":["与山夙有缘，因病转无欲。","僧斋聊卧起，散发何须束。","偶采芙蓉花，悠然出林谷。","秋风湖上亭，蘼芜飞属玉。"]},{"t":"卧疾四首 其三","f":"五言律诗","c":["行药至山馆，麋鹿相为群。","草木吐精华，宛如刺绣纹。","微雨日暮歇，南冈生白云。","何时拂衣去，长揖沧海君。"]},{"t":"卧疾四首 其四","f":"五言律诗","c":["朱槿日暮凋，玄发秋时落。","傲骨何嶙峋，习懒那可药。","采彼石上芝，引此林中鹤。","一室谁晤言，青山谢康乐。"]},{"t":"恭谒先世祖荣禄大夫都督公赐茔墓在杭州毛家埠","f":"五言古诗","c":["吾祖从靖难，功成受虎符。","镇越佐五朝，将星东南殂。","先皇为悼惜，赐葬兹山隅。","屡谕藩臣祭，碑版耀西湖。","云仍锡带砺，百世卫姑苏。","邈矣七叶孙，赋性一何愚。","不能挽强弩，但欲事操觚。","历官已廿载，落魄俨腐儒。","同侪贝锦张，亲戚从揶揄。","何令彼谮人，猴冠而当涂。","不望印累累，其如锥也无。","仅存三寸舌，终愧七尺躯。","偶来此行役，聊复荐萍芜。","石人衣薜荔，宿草莽故墟。","抚膺一长恸，洒泪柏为枯。","悲风起夕阳，愁杀夜啼乌。"]},{"t":"亲旧诗六首 其一 外父王选部禄之","f":"五言古诗","c":["泰山俨具瞻，匪直颂师尹。","一出秉铨衡，中外作标准。","朗月照浚谷，清泉流泯泯。","抗志圭组轻，萧然岩壑尽。","甥也馆于室，耳提谢不敏。","典谟日佩训，风雅时援引。","所至恒爱护，恐为友婿窘。","不减慈父恩，长恸德星陨。"]},{"t":"亲旧诗六首 其二 舅氏陆文学恒若","f":"五言古诗","c":["江东著伟姓，太宰迈常伦。","势可移山岳，位已无人臣。","一朝被蜚语，朱户生黄尘。","孙子余舅氏，青衿甘食贫。","硁硁守经学，湖乡少四邻。","时念同胞姊，扁舟入城闉。","澹泊不饮酒，慰籍多苦辛。","长逝渭阳水，愁绝慈闱人。"]},{"t":"亲旧诗六首 其三 先辈杨中丞子任","f":"五言古诗","c":["杨子青云彦，屡出佐明后。","昭毅昔论交，垂髫至白首。","树德于其躬，莠言不出口。","闽海同分符，阃藩并结绶。","堂上考大吕，幕下问小友。","眷顾成绸缪，乃与缔孙偶。","尺书付浮沉，竟执富儿帚。","感怀著斯章，冥冥非吾负。"]},{"t":"亲旧诗六首 其四 通家陆有道叔平","f":"五言古诗","c":["吾祖迈明德，结客豪长者。","平原秀士衡，正始翼风雅。","忘年缔密交，少岁荷陶冶。","潜盘西山阿，偃息青云下。","皎然白雪鬓，照兹绿玉斝。","明月投入怀，幽兰分满把。","对我欷歔言，老矣汗血马。","耆旧不憖遗，泪向寒泉泻。"]},{"t":"亲旧诗六首 其五 友人顾贡士从化","f":"五言古诗","c":["顾生一经生，而亦喜任侠。","闾巷弟畜我，俶傥无嚅嗫。","能射鲁连书，不问乐羊箧。","并载西园游，联镳南山猎。","痴绝虎头生，袖断如花颊。","青春容易掷，白发最难镊。","长安失意归，宿草飞黄叶。","尚忆平生言，独挂芙蓉铗。"]},{"t":"亲旧诗六首 其六 从叔隐君士扬","f":"五言古诗","c":["昭毅营东山，群从从之游。","第五足清旷，居然隐者流。","曾不问生产，乃与兄子俦。","把臂同入林，酒池日拍浮。","自为鸲鹆舞，间作竹枝讴。","行乐堪永年，达生宜白头。","门户正衰谢，斯人不可留。","咸也矧穷途，揽涕何时收。"]},{"t":"北游诗十八首 其一 捧檄偶然作","f":"五言古诗","c":["幽居谢鞅掌，披云卧高岑。","门有车马客，投以天上音。","呼儿拭我弁，揽镜整我簪。","薄言辞故里，于役越江浔。","负米愿良违，挽粟力不禁。","斥鴳安卑枝，匏瓜恋旧林。","夷险昧所履，倚伏还相寻。","傥来忽如寄，患得非吾心。","蓄无非常宝，敢羡纵横金。","养真尚寂寞，允为达士钦。"]},{"t":"北游诗十八首 其二 北游留别阳山顾愿","f":"五言古诗","c":["顾生言志高，乃住卑犹山。","常来访屠博，悲歌游市阛。","葛巾一角垫，长裾其色殷。","蹇步上大堤，桃花在窗间。","袖里金错刀，换酒良不悭。","宁待飞青霜，坐以凋朱颜。","皇皇脱长剑，送我西入关。","赠处两不语，流涕各潸潸。","世无四公子，弃客如草菅。","间有魏其侯，聊可与往还。"]},{"t":"北游诗十八首 其三 渡江","f":"五言古诗","c":["吴国渺何处，江流万里长。","布帆渡瓜渚，青山障朱方。","飒动高天风，吹愁还故乡。","戍楼当落日，饥乌野田密。","徒御步不前，行李何萧瑟。","欲问淮南津，就饭水边驿。","敢效祈父言，胡转予于恤。"]},{"t":"北游诗十八首 其四 泊广陵","f":"五言古诗","c":["晨发扬子渡，暮泊广陵城。","水部正闭关，落日舆梁横。","杂踏估船来，吴侬与楚伧。","野市乱灯火，恰如蜩螗鸣。","对酒愁不语，何处琵琶声。","间道往从之，青楼明月生。","自笑高阳徒，潦倒江州情。"]},{"t":"北游诗十八首 其五 次淮献河阳大夫","f":"五言古诗","c":["经国有大计，不外兵食足。","输挽类用兵，所贵在神速。","王程固有严，胄弁何为督。","娈童好如花，楼船大于屋。","行乐江以南，赫奕朱为毂。","盛夏方渡淮，黄河变平陆。","粒米乃狼戾，度支更约束。","简命旬宣臣，临水建牙纛。","八月造舟楫，十月运新谷。","哺乳百姓亲，挟纩三军燠。","况乃抱远略，道海通山谷。","廷议旌行能，玺书动盈幅。","伟哉转漕功，不使萧何独。","跅弛门下士，勉驾盐车轴。","期毋负知己，良友时相勖。"]},{"t":"北游诗十八首 其六 涉河","f":"五言古诗","c":["大河合淮泗，奔波若倾倒。","一瞬下千里，风帆疾于鸟。","我行逆其流，尺寸竟昏晓。","丈夫托蓬根，世事茹茶蓼。","穷途已倦游，况复苦秋潦。","揽挈黑貂寒，西风吹人老。"]},{"t":"北游诗十八首 其七 清郡馆郑丈","f":"五言古诗","c":["驱车入郭门，故人门挂席。","客子流离来，执手长叹息。","虞卿屩欲穿，侯生头尽白。","乐与朱家游，讳言赵邸客。","大损卖文钱，估酒日盈百。","任侠今寂寥，此有郑庄驿。"]},{"t":"北游诗十八首 其八 济上闻笛","f":"五言古诗","c":["孤笛江上起，片月随江流。","临风曲不断，韵水何悠悠。","杨柳折欲尽，梅花落更愁。","寒鸦散浦溆，残叶飞空洲。","楚客正独醒，闻之增繁忧。"]},{"t":"北游诗十八首 其九 七月廿四述思","f":"五言古诗","c":["凉风吹原隰，澹澹黄云生。","值此流离时，难禁陟岵情。","长恸高堂觞，言荐溪水蘋。","未始暌诸梦，常若见于羹。","更念倚门者，蓬首雪盈盈。"]},{"t":"北游诗十八首 其十 德州逢刘原检","f":"五言古诗","c":["公干吾密亲，迩来行色壮。","得意曲江游，十里紫丝障。","折得杏花回，春云在衣上。","南归衔使节，楼船晚相傍。","明灯照卫水，凉风来青嶂。","宿雁语沙中，纤月翻层浪。","对酒问前期，弹冠岂虚望。","从此舍章句，即可取卿相。","昼锦君多荣，奉职我无状。","清时好策勋，努力无遗忘。"]},{"t":"北游诗十八首 其十一 潞河客舍","f":"五言古诗","c":["岁晏众芳尽，朔雁江南征。","游子何不归，流离蓟北城。","阴阴土墙下，风吹枯桑鸣。","黄金与白发，此尽彼则生。","进退叹维谷，且问严君平。"]},{"t":"北游诗十八首 其十二 题长安主人壁","f":"五言古诗","c":["漕吏何为者，日与仓漕伍。","长安半月游，黄金散如雨。","乘月谒私门，带星候公府。","杯酒槩可亲，肝胆谁能吐。","势利无石交，斯言徵诸古。"]},{"t":"北游诗十八首 其十三 燕京寄上海朱邦宪","f":"五言古诗","c":["北风扬尘沙，玄阴片时结。","客舍寄如磬，羁身但存舌。","易水寒不流，西山欲飞雪。","梦见田先生，恍与荆卿别。","击筑苦无徒，悲歌夜不辍。","我友蹈海生，圭组久不屑。","游于酒人乎，而乃好奇节。","因救季将军，朱家心屡折。","吾岂有黄金，尊前为君设。","所以穷时交，古人多激烈。"]},{"t":"北游诗十八首 其十四 结客行与晋陵吴生","f":"五言古诗","c":["韩魏饶奇节，齐楚多辩智。","经学不足谋，结客非声利。","一言可借躯，万乘宁夺志。","虞卿急穷交，敝屣卿相位。","田生耻人疑，对客刎何易。","岂为颜面情，謟笑取容媚。","吾友延陵生，独抱千古意。","昔我困奸雄，三年两下吏。","邹阳不上书，张俭身何寄。","良朋每永叹，维子忧心悴。","不有匣金来，徒令怀璧坠。","谷风世道凉，浮云然诺弃。","长揖谢斯人，激烈尊前泪。"]},{"t":"北游诗十八首 其十五 塞垣行寄嘉禾朱尉","f":"五言古诗","c":["卫青屯上谷，连营肃旗鼓。","五道出将军，弓高与强弩。","系其贤王归，奇功不堪数。","坐拥武刚车，帐下式歌舞。","李广不得意，上簿至幕府。","是岂战之罪，拊心良独苦。","朱生蓬蒿人，掘起自行伍。","浮海斩吕嘉，英略无千古。","功奇祸亦奇，十年槛中虎。","长剑虽蒯缑，犹堪贾一怒。","丈夫身不死，塞垣报明主。"]},{"t":"北游诗十八首 其十六 少年行调长安客","f":"五言古诗","c":["结束何翩翩，相逢洛阳陌。","流水照清扬，春风披绿帻。","俨然傅脂粉，相传化闳籍。","羞称霍家奴，云是馆陶客。","歌舞谁不怜，婉媚莫可逆。","沾沾喜任侠，黄金得还掷。","珠因弹雀损，锦以斗鸡坼。","而多青楼期，欲赴身无百。","且与酒人游，暂入蓬蒿宅。","枕藉唯衮衣，何有一缝掖。"]},{"t":"北游诗十八首 其十七 留别京邑友尘","f":"五言古诗","c":["杖策长安门，言别长安客。","何为曰归时，翻使旅愁迫。","侠游多酒人，祖道临南陌。","马蹄雪中花，车轮冰上迹。","再歌毋庸归，乐酒暂今夕。","长剑挂左骖，白虹走前席。","荆玉罕人知，劝吾宝燕石。"]},{"t":"北游诗十八首 其十八 汶上阻雪","f":"五言古诗","c":["我行阻徐方，日夕望吴国。","积雪覆皋原，千里同一色。","门前偃栅横，屋际孤烟直。","黄河冰正坚，芒砀云来黑。","狡兔潜以伏，饥鹰竟何食。","客子煨枯蓬，主人舂残稷。","何日见朝阳，肃彼南归翼。"]},{"t":"金昌篇","f":"古风","c":["青山浮震泽，紫霭凝沧溟。","既庶古吴邑，有美金昌亭。","金昌亭子碧城趾，傍临大道平如砥。","象纬台窥万雉雄，阊阖门开千片绮。","垂阳绣陌春载阳，芳草朱桥满路香。","甲第连云巢翡翠，人家临水扑鸳鸯。","玉楼天上近，金屋民间藏。","秾彼桃李葩，映此鹦鹉觞。","茂苑郁葱茜，胥江艳花月。","丽藻飞彩毫，芳尘袭罗袜。","清歌鸣凤舞惊鸿，宝树琼轩乐未穷。","芙蓉散乱妆台锦，兰麝氤氲步障风。","桂醑浮波玉为馔，高堂屋壁金珠缘。","虽非戚里与皇家，万户千门烂若霞。","玉帛南邻耀皎日，簪缨北里生光华。","清时富贵偏多暇，少岁欢娱昼为夜。","宅中歌笑尽金张，座上风流总王谢。","泽国无烦拥画轮，吴侬飞楫浪如银。","湖舸载将西子去，渚花开作馆娃春。","蝉鬓宫云薄，蛾眉山月新。","为雨乍逢情易合，倾城再见价难论。","由来金谷明珠贱，却笑临邛绿绮贫。","迷花醉月靡年载，相逢剩有朱颜在。","长风可破月可拾，直欲扬舲泛沧海。","沧海回波不复来，拂衣高眺吴王台。","吴王宫阙莽难辨，棘荆麋鹿令人猜。","棹歌犹唱乌栖曲，百花洲上蘼芜绿。","一川春雨鹧鸪鸣，鹧鸪声里年华更。","身世隙驹影，富贵草头露。","万物不可齐，士也何须遇。","园有桃，歌且谣。","半生落魄无推择，大块与尔同逍遥。","长镵朝过买臣里，短衣暮上伯通桥。","举案徒自恭，庑下竟寂寥。","不挂会稽章，空老吴门樵。"]},{"t":"匣剑行","f":"古风","c":["生长夫差国，家住专诸里。","锻鍊昆吾成，一匣明秋水。","秋水泠泠声绕扉，凄清中夜蛟龙归。","空庐独抱朗月卧，高天飒动霜华飞。","提携神物无人觉，何来白虹常在握。","锋芒卫霍耀天山，精灵荆聂倾河岳。","结客纷纷向五陵，呼卢博采且浮沉。","宁输百万留三尺，悬在腰间酬寸心。","鸊鹈新淬光如彗，照见人间不平事。","玉玦金镮日日间，匣中一掬明珠泪。","严城吹角秋夜清，风凄月肃邻鸡鸣。","揽衣起舞欲拔剑，无乃岁久青苔生。","莫邪空老无人齿，世人共宝铅刀耳。","幕南塞北行路难，酬恩报怨竟谁是。","沦落沉埋一蒯缑，耻将弹铗动诸侯。","丰城不掩干霄气，越石何嗟绕指柔。"]},{"t":"对酒歌","f":"古风","c":["宇宙自万古，人寿无百年。","我生之前漫无纪，我生之后殊杳然。","中间百年何太促，始觉人世徒堪怜。","况乃寰区受羁束，曷能蓬海求神仙。","幸有金阊醇酎美，一斛不直三千钱。","沽来快饮日不竭，赖兹薄禄如流泉。","清者可中圣，浊者可中贤。","伯雅或在后，季雅或在前。","公荣不择侪辈饮，季伦欲就邻家眠。","君不见花开枝上何娟娟，春风吹落随寒烟。","又不见云行空外百态妍，须臾散尽苍旻天。","玉山常倾倒，桑田任播迁。","胸臆从教块垒散，形神自尔魁梧全。","一日可兼十日饮，百岁能当寿一千。","始信壶中有日月，不与人世同弃捐。","沉冥至理久自悟，糟丘为我生青莲。"]},{"t":"东览篇","f":"古风","c":["出门鲜徒侣，看山过东越。","身披荷芰衣，来渡琅玕筏。","会稽之郡藏云中，海岳灵区第几峰。","千岩万壑望不尽，一一秀出青芙蓉。","溪流嗽石喷晴雪，山水清音相映发。","林间吹落兰亭风，松下飞来镜湖月。","石暗花迷失去津，禽鱼鸟兽能相亲。","峥泓萧瑟不可测，此中疑有箕山人。","苍旻为栋云为幕，禹穴幽奇可栖托。","绝壁巑岏啸夜猿，逍遥梦见骑黄鹤。","清晨晞发凌高台，风吹飞花去复来。","旭日如珠走沧海，赤霞为驾驱天台。","方丈蓬莱今可至，居然便有凌云思。","金宫银阙何必求，一丘一壑随吾志。","君不见东山高卧支许从，挥麈玄言若可终。","又不见芳辰韨褉临清池，茂林脩竹堪忘饥。","谢公勉为苍生出，十年閒却登山屐。","右军自失王蓝田，归来誓墓意惘然。","二贤信是人中龙，霖雨当时仰望同。","考槃一室已千载，至今林下生清风。","偶然得失未忘念，令人却羡双冥鸿。"]},{"t":"春游篇寄晋陵吴生","f":"古风","c":["穷愁逼逼空叹息，远游冠在犹堪拭。","伯通桥下春水流，布帆一幅千里游。","芙蓉湖波绿如染，罨画溪头山几点。","花明月白不知夕，髣髴扁舟重入剡。","旧游曾识延陵生，莫逆穷交一步兵。","且作平原十日饮，安事夷齐千载名。","寂寞圌山老都尉，迟我碧桃花下醉。","锦江春暖浪俱香，赤城霞流山失翠。","金焦遥作两青凫，水面飞来扑玉壶。","万里长江限南北，令人长忆孙伯符。","燕子矶头燕子飞，凤凰台畔柳依依。","看花偶入长干寺，策杖还须到翠微。","荷衣脱下白纷纷，尽是钟山松上云。","辟支洞口金光草，兜率岩中宝藏文。","摄山自古多灵药，归来始践徵君约。","悠然置我丘壑间，高吟梁父惊猿鹤。","吾笑殷中军，废后书空竟莫闻。","又叹阮遥集，一生当著几两屐。","此身不带封侯骨，朅来幸有烟霞癖。","黄金朱芾求不来，白云青山随可得。","不因未了向平缘，五岳追寻孰我先。","知君亦是沉冥士，寄此春游汗漫篇。"]},{"t":"放歌行寄长安旧游","f":"七言古诗","c":["碧桃落尽青春老，黄金不铸朱颜好。","男儿策名须及时，衰迟徒遣忧心捣。","少年投笔欲邀勋，西入长安谒圣君。","公车不献长杨赋，都邑先传喻蜀文。","朱门先达如畴昔，留驩得接夔龙席。","鸣环振佩声锵锵，琼筵宝幄乐未央。","暂同良夜醉鹦鹉，期共清朝仪凤凰。","辉光草木俱生色，假使白头还可黑。","意气如山不易倾，立谈元可取功名。","借筋画成扶汉鼎，箭头书去破聊城。","居间然诺良无负，彊灌能胜一石酒。","藩车日赴孟公期，金钱夜作爰丝寿。","骏马花骢白玉鞍，濯龙鸣凤近金銮。","英盼自堪回绛灌，雄图非为斩楼兰。","得意能将知己酬，此心未始羡封侯。","一言不合拂衣去，五陵游侠还相许。","斗鸡走狗出长楸，安能咄咄书空语。","自是当时桓茂伦，历落嵚崎可笑人。","今日低头在草莽，放歌一曲千山春。"]},{"t":"观舞篇","f":"七言古诗","c":["春宵曲宴通兰房，亭亭玉树生夜光。","绣幕遮风银烛定，纷纷妓乐俱成行。","中有燕姬善楚舞，当场可以掌中举。","翩跹喜曳鲛人绡，柔弱才胜翡翠羽。","应节依歌不自持，疾徐宛转能擅奇。","明珠盘里相错落，惊鸿天外来差池。","徊翔素腕飞香雪，虚空屡顿凌波袜。","五尺芙渠摇绿波，一片轻云荡明月。","颦容慢睇如有情，步摇条脱断续鸣。","公子歌谣惟燕燕，佳人名字只卿卿。","舞罢低回整金凤，矜娇顾影嫌钗重。","羞称十五嫁王昌，登墙三载曾窥宋。","漫将长袖拂芳尘，自是行云行雨身。","恍惚高唐梦中见，敢云平视甄夫人。"]},{"t":"听曲篇","f":"七言古诗","c":["绿窗窈窕通明月，朱弦奏罢何疏越。","燕姬艳舞方具陈，郑女清歌相对发。","玲珑宛转绕翠屏，梁尘飒飒花冥冥。","师传翻使惊恊律，心妙直欲追秦青。","已听泠然振林木，复闻馀响流空谷。","将无哀乐动人心，苏门之啸秦庭哭。","当筵但见春融融，无限玉树摇东风。","周郎欲顾曾无误，延年女弟徒称工。","新声能令旧声变，贯珠不断危如线。","偶觉凄清拂黛蛾，时为掩抑看团扇。","画栋轻云夜不飞，凤凰肯逐箫声归。","但怜白雪知音少，岂是红妆绝代稀。","云鬟零乱歌才阕，东方欲明银烛灭。","淳于一石自沉酣，不使冠缨座中绝。"]},{"t":"醉道士歌题弇山园藏卷","f":"七言古诗","c":["列真之宇太微宫，碧桃千树吹春风。","相逢尽是餐霞客，翩跹长揖壶中公。","壶中跳入杳无际，金台银阙非人世。","玉液涓涓汇作池，黄流泯泯倾如注。","式歌有酒旨且多，三三两两朱颜酡。","漫笑真人能服炼，谁知老子亦婆娑。","髣髴步虚行复止，曲肱聊隐乌皮几。","背痒欲倩麻姑搔，觉来失却王乔履。","牛饮鲸呼总易醺，牵裳濡首乱纷纷。","拍浮倒蹋琼科案，酩酊那开蕊级文。","土木形骸恒伫立，手持玉笛吹不得。","平头奴子力不禁，扶携踉蹡将安适。","浪游五岳穷三山，联袂尽是桃花颜。","绛河迢递谁相待，上元夫人名阿环。","会时不问胡麻饭，解酲五斗何足算。","牵出青牛欲倒骑，黄冠欹斜白发乱。","此中玄妙识者谁，仙药元从曲蘖遗。","披图展卷心自醉，颓然此辈真吾师。","主人谓若幸无负，我且斟若以大斗。","倘画当年醉步兵，江东张翰应居首。"]},{"t":"娄水行访曹子念作","f":"七言古诗","c":["湖头暂借渔艇子，春风吹过碧城趾。","具区初月挂吴山，沧溟紫霓含娄水。","夜潮忽涨杨柳陂，片帆却向桃花驶。","眠鸥宿鹭惊且鸣，棹歌不断欸乃声。","中流闻鸡曙星耿，落花飞出海上城。","停桡未入琅琊墅，搴裳先过曹丘生。","萧斋兀尔枕书卧，乌皮一几青毡破。","问我经时何不来，袖中遮莫有七哀。","大笑吾生太痴绝，病腰犹为五斗折。","屡蹶霜蹄不知止，仪也直欲亡其舌。","丈夫雄心谁则知，吁嗟有志无其时。","公荣未得即濡首，匡鼎相逢且解颐。","放歌一曲情无赖，君自芝兰我萧艾。","陈蕃有榻空梁悬，解来徐孺眠花前。","聊伴曹生日击缶，洋洋风雅衔在口。","绵蛮不作吴侬言，喑哑能驱小巫走。","一斛珠玑错落明，俨然分惠盈五斗。","吾还怪尔爱独醒，酒人只在弇山亭。","迩来不饮真寂寞，纵酒无愧天上星。","借来艇子且教去，平原十日须沉冥。"]},{"t":"谢都护歌","f":"古风","c":["谢侯少岁学击剑，手绾飞虹腰掣电。","术精乃去学兵法，战阵钲鼓靡不合。","被命造舟永嘉山，长鲸道遇手自搏。","几欲论功登将坛，落落不偶空据鞍。","阅世荣名何足齿，闾巷沉浮聊尔耳。","短衣射虎姑苏台，闭户铸剑干将里。","买得桃花一疋驹，骑来沽酒金阊美。","世人失意汩汩忧，羡君能自沾沾喜。","为嫌偪促城之舍，新开别墅虎丘下。","窗中乱扑青芙蓉，竹树萧萧绕台榭。","侠游酒伴惯住船，斗鸡走狗都翩翩。","春草射麛秋放鹯，相逢欲赋子之还。","座客恒满能击鲜，人各取醉斗十千。","虽无铜山擅铸权，囊中不乏子母钱。","吁嗟燕颔头未白，黄须森森尚如戟。","江南秉钺旬宣臣，旧是永嘉来往人。","即今推毂易为力，功名转眼能自新。","劝君努力报知己，匣中毋遣神龙死。","君不见余也十载伤羽毛，身同鹪鹩困蓬蒿。","提携拂拭竟谁是，哀鸣日夜徒嗷嗷。","于戏男儿四十不能自附青云豪，尚尔坎坷肮脏沉下僚。","赠君短歌还自嘲。"]},{"t":"短歌行赠王四丈赡美","f":"古风","c":["男儿何必纡朱紫，但令布素恒如此。","又何必侈金帛，所贵人生在意适。","琅琊群从鸾与凰，上林太液纷翱翔。","第四偶然恋桑梓，羽毛楚楚口吻香。","白眉未尝结青鬓，未遽霜海燕双栖。","绕梁语芙蓉，一照满镜芳。","千金鹔鹴裘易解，日醉鹦鹉杯难忘。","司马才遗中人产，对人无奈多青眼。","沙田种秫久不登，座客犹誇识信陵。","平生倜傥无嚅嗫，沾沾聊自喜任侠。","余生落魄数数奇，十年归隐南山猎。","无端痛饮白玉浆，有时脱赠莲花铗。","每承然诺肝胆倾，岂是论交在眉睫。","跻彼弇山堂，友于花萼尊俎光。","再过娄水宅，彩衣戏舞娱头白。","人见颓然醉花月，不识人伦自尔能昭揭。","人见生平曳纨绮，不识穷交可以托妻子。","谷风再赋友道凉，吴侬情逐云飞扬。","三秋门前正罗雀，一卧肘后生垂杨。","不有君来破岑寂，翟公自署徒慨慷。","眼中石交竟谁是，酒酣击筑天苍苍。"]},{"t":"江风行与朱图山泛楼船作","f":"七言古诗","c":["长江万里吹天风，将军置酒楼船中。","楼船忽奏军中乐，无乃黯惨蛟龙觉。","山川出云历乱飞，疾来掩我白日晖。","中流汹涌俱辟易，人谓如此将无归。","将军自是湖海客，神气自若催挂席。","浩荡洪流欲挽回，崩奔巨浪能冲逆。","渊渊徐起回风挝，长驱直指扶桑涯。","蜃气氤氲辨城阙，鲸波蹴浪翻空花。","分明栖息匡庐下，碎瀑飞泉明月夜。","恍惚窗牖峨眉端，雪片纷纷六月寒。","须臾暝色垂垂黑，前队戈船左右翼。","咫尺蛟龙欲扣舷，夜光那向怀中匿。","壮图寂寞何为乎，余亦从君击唾壶。","老骥能思千里不，百万犹供一掷无。","人寿河清不可俟，富贵不来行乐耳。","世间多少弱男儿，觅人颜色沾沾喜。","曾忆长江牛渚边，温峤焚犀夜放船。","英雄志业莫可测，酒酣拔剑心茫然。"]},{"t":"塘上行逢友人顾愿作","f":"古风","c":["吴宫二月莺，啼乱金阊柳。","游子长安归，春风吹鹢首。","鹢首重重桃李花，枫桥塘上故倡家。","绿水依然绕阡陌，青楼忽听弹琵琶。","琵琶声出垂杨里，李延年家高髻姊。","自言有客深自藏，落魄江东虎头子。","拍浮濡首酒池中，何为染指阿房美。","平生痴绝将无同，我辈钟情乃如此。","相逢不赋子之还，对酒高吟娇女篇。","兴来不用常杯酌，其奈囊空无一钱。","君不见马长卿，临邛一往有深情。","又不见阮仲容，鲜卑之婢累骑从。","尝闻古人贵达节，区区礼岂为我设。","少年行乐须及时，飞花转眼纷如雪。","还惜昂藏一丈夫，凭陵啸傲高阳徒。","麟阁荣名常在不，首阳饿死何为乎。"]},{"t":"月下渡淮歌与马孟李三都尉舟中言怀","f":"古风","c":["日落淮水黄，月出淮水白。","水流向东南，客行自西北。","辞家见月两回圆，长路悠悠始一千。","簿书期会如束湿，卒史胥徒横索钱。","橐存无底空所有，但见三星恒在罶。","身世漂零只酒尊，凉露凄蝉动高柳。","从事诸君尽弃繻，金堤赤岸争先驱。","吁嗟百万任狼藉，何事囊粟号侏儒。","吾生一饱了吾愿，坐看鹪鹩飞不远。","马控龙媒自有人，门藏金穴曾无援。","久拟山中赋考槃，何然燕垒巢其端。","漆园傲吏日偃蹇，竹林酣士多摧残。","夜深月照芦洲寂，楼船有楫何须击。","最喜黄头善掺挝，况邀白帻能吹笛。","淮阴黯惨生悲风，座中杯酌莫教空。","若过韩侯钓鱼渚，便为长跪酹英雄。"]},{"t":"游吴山醉歌示越中同游","f":"古风","c":["吴人浪游越，越山旧名吴。","吴山窈窕如画图，芙蓉乱扑城之阇。","云英不远紫微省，杏花偏近黄公垆。","解衣贳酒独感慨，还上高台听鹧鸪。","鹧鸪不为啼春雨，似诉吴越兴亡语。","般乐夫差首己濡，忧勤勾践胆能茹。","偶尔凭陵一跳梁，毕竟山丘共首鼠。","草上同飞望帝魂，宫中曾献捧心女。","吴山越水春融融，吴王越霸归东风。","白驹度隙促短景，朱花散綵成飘蓬。","乍来一笑已陈迹，兹山千古青无穷。","即今箫鼓锦城乐，但识屏翰皇图雄。","吁嗟黄金不买绿酒醉，何乃愦愦人世亶不聪。"]},{"t":"钱翁歌为磬室山人寿","f":"七言古诗","c":["钱翁不是蓬蒿人，自称吴越诸王孙。","布衣不受缁尘染，混俗能将白眼存。","栖迟陋巷蓬蒿翳，抱膝长吟靡年岁。","家藏万卷不知贫，更倚丹青曾绝世。","巴江急峡巫山峰，汉时古柏秦时松。","钱翁下笔无数点，便觉烟云千万重。","长康安道名谁称，世情都无神自胜。","屦集常憎户外尘，萧然一室如悬磬。","钱翁不满五尺长，意气能飞千仞霜。","等閒不受诸侯币，虚左曾持公子觞。","吾家都护弄柔翰，风流寄兴东山畔。","傍水新开燕子楼，临花高捲鸳鸯幔。","爱惜长干刘采春，当时西第几留宾。","坐中不少严夫子，幕下常多郭舍人。","自是钱翁交莫逆，春山花月同穿屐。","如今花落月西沉，但见钱翁头尽白。","黄公垆下莫经过，吹笛山阳感慨多。","凄凉若问吴趋第，四壁徒存一雀罗。","翟公门前何所有，春风乍上新杨柳。","百斛金阊绿玉浆，沽来且作钱翁寿。","钱翁七十意何如，云在青天任卷舒。","他时倘画通家子，丘壑偏宜谢幼舆。"]},{"t":"郑客行寓清郡赠中伯丈","f":"古风","c":["仲尼老于行，柳下援而止。","殊无怀土情，郑客乃如此。","郑客吾乡老缝掖，不根嫚戏无推择。","西游落魄走邯郸，国有贤王虚左席。","日留朱邸曳长裾，贵幸何须驷马车。","但虑才高忌严忌，谁言赋不如相如。","冠缨曾绝感知己，锦茵醉吐花靡靡。","无端压倒玉堂人，只因撰出金楼子。","内家日给买文钱，外舍私为桃叶怜。","解将交甫明珠佩，博得文君绿绮弦。","秋风客散平原第，齐东陋巷蓬蒿翳。","不无岳牧致苞苴，自有州司能拥彗。","我来犹得称通家，相逢烂醉听琵琶。","卫水清霜照明月，鹔鹴裘映芙蓉花。","自言仅免穷愁逼，无奈头无一茎黑。","纵梦非熊入后车，不如安载归乡国。"]},{"t":"吴姬行为四明沈嘉则买妾赋","f":"七言古诗","c":["吴姬二八颜如花，翠帷珠箔藏卢家。","暂许春风吹裙带，未容燕子窥窗纱。","妆台才掩临窗绣，皓腕霜明映罗袖。","蛾眉效月一痕新，柳腰学舞三眠瘦。","瘦减腰肢似沈郎，当年未许嫁王昌。","不识红妆堪换马，但知绿绮可求凰。","遨游忘草郊居赋，江城花县啼莺路。","鹴裘时解茱萸湾，画舸偏经桃叶渡。","吴阊新水泛双鸳，丽藻文漪锦浪翻。","毫端幻出花千树，剩得娇枝解语言。","含娇含态情难说，为雨为云梦无歇。","巫山峡绕曹娥江，襄王台在禹王穴。","采莲越女湿绡衣，短棹穿花过钓矶。","瞥见吴姬不相识，恍疑洛水神仙归。","约开莲叶隔花语，为问馆娃宫几许。","依依杨柳苧萝村，此是西家捧心处。","错落明珠吐凤钗，陆离端锦合欢裁。","昔时越艳归吴去，今日吴姬入越来。","甬东山水蓬莱岛，朱颜绿鬓同偕老。","风流愿比贺季真，镜湖春色年年好。"]},{"t":"苏生行","f":"古风","c":["苏生纵横客，寂寞休明世。","尺寸无所成，坐叹流光逝。","少岁曾为南粤游，尉佗椎髻最难柔。","军前长揖无数语，遂令面缚閒戈矛。","归来牛酒相慰劳，上功幕府寝不报。","翻然结客少年场，五陵豪杰亲除扫。","解装犹剩千黄金，遍置鸳衾与凤簪。","好将陆贾平生橐，结得徐娘既老心。","春明门外花如绮，羽林缇骑佻佻子。","相逢大快共樗蒲，绝叫狂呼卢与雉。","百万常输囊屡捐，凄然击筑夜无眠。","荆卿远去渐离老，孤剑寒风易水边。","东归肮脏身何寄，数椽如线邻萧寺。","短衣弹雀逐群儿，长镵采药遗仙吏。","看君体骨良不恒，面如紫石何棱棱。","谁言山泽常如此，忽有风云或可乘。","男儿七尺须奇节，黑貂何必愁鹑结。","阴符一匣在床头，莫使灵文久磨灭。"]},{"t":"短歌与一二僚佐登城楼作","f":"七言古诗","c":["吴钩锈涩不能鸣，匣中隐隐青苔生。","高天九月霜华白，草木黄落夫差城。","夫差城中谁作苦，摧眉折腰在行伍。","父书徒读亦何为，投笔十年无比数。","藏活曾栖广柳车，沉酣屡谪西曹簿。","男儿肮脏安足叹，世上纷纷鼠变虎。","卫青亦是主家奴，须臾功成享茅土。","出无知己仕无媒，不如将身隐屠沽。","丈夫空自羡雄飞，今日登临对落晖。","满目山川非异国，仲宣何事泪沾衣。"]},{"t":"谢都护游山歌","f":"七言古诗","c":["谢家雅有东山兴，朅来许我才情胜。","少年有事弋与渔，垂老无心负且乘。","春风满地吹接䍦，青山绿酒堪忘饥。","双艇移来疾于骑，五湖便是高阳池。","林中排调日酣畅，三春共蜡屐几两。","自是狂奴去复来，至今痴叔犹无恙。","吴王台馆久棘荆，山丘尚被吴王名。","云兴雨散竟何托，雄飞雌伏徒营营。","君能于此了无累，黄公垆下颓然醉。","迩来喜怒谁得知，褰帷且问如花妓。"]},{"t":"燕京夜雪篇","f":"七言古诗","c":["北风吹沙日无光，北门寂历鸣枯桑。","须臾暮雪飞陋巷，蓬扉不开卧欲僵。","西邻客子忽排闼，苍头蹇步持壶觞。","恍如层冰甫挟纩，又似幽谷回春阳。","何暇秦篝与齐缕，不去弹棋共格五。","乡语绵蛮自少文，行酒峥嵘能用武。","因忆边城雪作山，崎岖万里玉门关。","冰连瀚海悬军入，冻断交河探骑还。","以身许国宁惮死，安顾裂肤仍堕指。","今夜相逢杯酒间，何如此辈沙场里。"]},{"t":"行行且游猎丁丑九月作","f":"古风","c":["少岁从军出武威，兜鍪日耀生光辉。","沙场大小七十战，数奇归掩南山扉。","南山近有白额虎，会须烦我大黄弩。","朝来结束过蓝田，马如游龙辔如组。","入林黯惨路不平，披开荆枳飞鸟惊。","乱石崔嵬垒如屋，咆哮万壑阴风生。","顾盼凭陵了无觉，应弦即倒何须搏。","男儿本意重生擒，飞而食肉良不恶。","甲卖弓藏一十年，偶因射猎泪潸然。","扪虱若谈当世务，白额岂在南山前。","头足于今变冠履，取民脂膏充簠簋。","假彼绣斧得横行，缚取贪残猛虎献天子。"]},{"t":"隐者词焦山寄客","f":"古风","c":["伯成耦耕耕且锄，务光避世世情无。","古来隐者不以帝王易，何况区区赵孟三公乎。","山人颓唐隐者姿，萧萧肃肃孤松枝。","紫芝黄鹤久不作，清风朗月恒相思。","相思不可见，远隔江之湄。","不寄投湘赋，唯吟招隐诗。","碧桃开遍绿水洲，山人犹在人间游。","富春矶閒海鸥下，鹿门山空猿鹤愁。","诸侯筐篚不足贵，天子安车何必求。","但须寂寂山之丘，明月为侣云为俦。","庶几不愧乎隐者流。"]},{"t":"山人劝酒","f":"古风","c":["灼灼桃花，濯濯杨柳。","溪山窈窕溪水流，武陵人家犹在不。","柴门不闭春风轻，山人衣上春云厚。","相逢莫使青松疑，世间尽用黄金寿。","原尝春陵千载人，嵇阮山刘一杯酒。","贱亦不足凌，贵亦不足凭。","雪山有时燠，温泉或可冰。","高岸为谷，深谷为陵。","诗人岂欺我，倚伏多相仍。","山人劝我酒，旨酒清如渑。","汉家功业在天上，吹箫屠狗之辈坎坷历落来攀登。"]},{"t":"还山吟","f":"古风","c":["还山吟桂花，松子秋云深。","山人还山抱孤琴，空山猿鹤来相寻。","披裘何必登遥岑，远公自有东西林。","东西山色看皆美，一入林中可以止。","土木形骸无所拟，悠悠忽忽恒如此。","再歌还山吟朱颜，俄受白发侵还山。","欲俟买山金，无金终负还山心。","一瓢一锡且随意，许由巢父百世之上为知音。"]},{"t":"柳花歌金陵送客","f":"七言古诗","c":["吴宫濯濯春杨柳，东风吹花满渡口。","摇烟拂水总无关，缀雪沾霜竟何有。","沧浪漫使搴人衣，武陵乱约桃花归。","自是青春留不住，非因黄鸟蹴能飞。","芳草晴丝引江渚，飘扬千里同君去。","远游谁遣迟萧郎，风流展转思张绪。","建业青山绕大堤，女郎团扇扑高低。","往来不见临春阁，且入长干送马蹄。"]},{"t":"草阁谣戊寅夏志感","f":"古风","c":["子云草阁无数椽，风雨不蔽何萧然。","常抱明月巢其端，归鸿鸣凤同翩跹。","何物黄狐爨下游，雄飞雌伏将焉求。","狡焉日欲穿我屋，何不尔思正旧丘。","长谣送尔归，吾自掩吾扉。","庭梧日徙倚，山桂生芳菲。"]},{"t":"黄河客舍歌","f":"古风","c":["杖策渡河来，止舍河堤下。","衰柳当其门，荒荠生在瓦。","中有少妇能具餐，旧襦掩骭馀双鸳。","剉草饲我枥上马，牵藤挂我腰下鞬。","客舍金钱真自惜，那堪一粲垆头言。"]},{"t":"忆闽中旧游有序","f":"七言古诗","c":["忆昔海波乍飞扬，长鲸吐雾白日黄。","家君作镇闽之疆，手提三尺擒其王。","幕中尽举万年觞，铙歌凯曲何铿锵。","从军未许称王粲，草檄无烦借孔璋。","曰余小子不好武，当筵漫学赋鹦鹉。","细柳营前羽戟閒，芙蓉幔里蛾眉妩。","玉勒骄嘶踏落花，银筝缓调鸣朱户。","枚皋诙笑类俳优，束晰嫚戏能消愁。","斗鸡蹴鞠沉里巷，射麋罝兔空山丘。","喜为豪士岸白帻，曾见胞人傅绿韝。","贵游造请刺磨灭，博徒之辈聊延结。","大道相逢脱佩钩，交欢岂必归金埒。","青州从事玉液香，红绡荔子冰肌洁。","垆头且醉郑樱桃，一曲新声夜月高。","怀中自有明珠卖，座客何须绿绮挑。","少年行乐常如此，宁知花谢秋风起。","拂衣长揖武夷君，扁舟直指吴江水。","归来寂寞夫差城，年华屡傍五柳更。","蓼莪再读涕泗盈，于今白发有几茎。","怀谗抱谮日不平，我思旧游歌且行。","匣中夜夜双龙鸣，犹堪报国图峥嵘。"]},{"t":"春日游金陵牛首山寺漫拟龙门应制之作","f":"古风","c":["万柳暗驰道，飞花度宫阙。","匹马碧城隈，晓向长干发。","长干髣髴汉长杨，玉露金茎满路香。","仙人高观分鳷鹊，帝子灵台集凤凰。","别有双峰霄汉外，空翠飞来扑衣带。","鸟道孤悬出梵林，松涛十里藏天籁。","层岩嘉树郁菁葱，叠嶂流霞一万重。","琳宫嵌入云中壁，绣阁徊翔木末峰。","丹青丘壑图难尽，绮错山川望不穷。","瑞气祥光蔼畿甸，周京汉苑氤氲见。","鸣凤楼台散若星，凿龙池水澄如练。","鹫岭朱幡俯太清，雁堂绀宇千花盈。","明月玲珑菡萏塔，青山窈窕芙蓉城。","明月青山恒若此，金仙绣佛同终始。","龙藏岧峣七宝台，麒麟鹦鹉献花来。","纤埃除埽空门净，日月照耀中天开。","霓旌披拂云旗展，万乘辉煌曾驻辇。","金陵定鼎卜千年，虎踞龙蟠此后先。","五岳区中谁王气，三山海底孰神仙。","秖遏北平戎似雨，故遗白下草如烟。","明时未效卷阿颂，在野聊成揽胜篇。"]},{"t":"京口桃李园作时戊寅春赵敬甫邬汝翼陈永年同游","f":"古风","c":["三月弭帆京口渡，大堤十里垂杨护。","故人行乐桃李园，恰有花开一万树。","烂漫常生五色霞，氤氲散作晴空雾。","赤城忽拥锦江流，朱方即是琼台路。","游子来回总是迷，佳人采摘还相妒。","拾翠寻芳乐未休，相逢且作少年游。","斗鸡走狗花前队，秾李夭桃树底讴。","莫将螓首疑闳孺，更傍蛾眉认莫愁。","团扇扑时粉蝶乱，?船飞处红英浮。","沉酣聊且眠金谷，潦倒那堪控紫骝。","但恐芳菲易销歇，长江寂寂流明月。","黄金纵有南山高，难买春花秋更发。","片片飞花踏作泥，阴阴桃李自成蹊。","开时不尽一杯酒，孤负枝头黄鸟啼。"]},{"t":"申太史招饮邸第席上漫呈","f":"七言古诗","c":["八月凉秋动城阙，朔方候雁催群发。","防秋羽骑夜授衣，破贼将军朝秉钺。","无能辇下请长缨，投笔书生志未成。","黑貂久作长安客，青苑谁深故苑情。","玉堂学士伊周侣，退朝为我设鸡黍。","相对惟多桑梓言，不作金华殿中语。","幸睹熙朝日月新，欣逢河岳又生申。","扫门岂是通私谒，推毂偏能问故人。","惭余射不能穿札，束发空教慕奇节。","归卧南山一十春，马无羁勒车无辖。","我辈何须尺寸功，但令公等致时雍。","愿言王者称无外，肃慎呼韩作附庸。"]},{"t":"春日宴弇山园呈琅琊长公","f":"古风","c":["长公天下士，子房安石差相似。","弇园美无伍，方丈蓬莱堪比数。","珠帘翚阁白云中，苍峡鱼梁绿水通。","高张云锦耀日月，披拂玉树吹春风。","岩藏洞复忽欲暝，花扑飞泉路不定。","萧瑟峥泓不可言，长吟清啸蛟龙听。","一望烟霞草木深，且耽丘壑不为霖。","玄亭寂寂无丝竹，自有泠然山水音。","春宵花月欢为剧，入林酣畅仍浮白。","相看尽是饮中仙，何必平泉醒酒石。","惭余落魄久悬鹑，自是嵚崎可笑人。","葛彊头白无推择，常伴清游石季伦。","终使揶揄满人口，青蝇白璧亦何有。","不能废我啸与歌，熟读离骚痛饮酒。","古来出处随乎时，赤松之游良可师。","虽然得意东山卧，无奈苍生有所思。","丈夫磊砢无多嘅，要使身名俱受泰。","弇园岁月一杯中，长公心事冥鸿外。"]},{"t":"饮大司成姜公园池席上敬呈","f":"楚辞体","c":["姜公言行为世轨，好似东京李元礼。","升堂便比登龙门，暂与同舟以仙拟。","一出曾为帝者师，门如市兮心如水。","吁嗟古道人莫容，意色萧然可以止。","为园筑室江之干，移得青山满绿湍。","五株初种彭泽柳，九畹先滋湘水兰。","披襟坐对秋月朗，更看宝树明虚幌。","碧池隐有凤凰毛，青云已著鹓雏想。","草木禽鱼亦有文，石渠金马梦氤氲。","常摇白羽团如月，不著朱衣烂若云。","考槃在涧聊暂寄，矢心欲揽清时辔。","何来海内忘年交，孔公座上祢生醉。","知君自是名教人，桀溺何须笑问津。","汲黯尚为前日戆，马卿犹是旧时贫。","苍生欲夺丘园志，白发能强负荷身。","相逢不尽漂零叹，对我常将青眼颦。"]},{"t":"吴兴潘中丞上蔡张参伯小集草堂漫成长句","f":"七言古诗","c":["杏花开满夫差城，城头初月纤纤明。","春风幸不弃岩穴，蓬蒿亦自来簪缨。","谢公暂著东山屐，步兵本是江东客。","一斛葡萄鬓未星，千里莼羹盌浮碧。","萧萧瑟瑟无歌钟，清音忽起庭下松。","楚云生栋帷菡萏，吴山供客餐芙蓉。","白驹空谷谁继响，鸣鹤九皋声朗朗。","风标不似世中人，霞举犹为天际想。","知君自是夔龙宾，何事江湖欲问津。","为霖为雨若有待，一丘一壑非其伦。","愧我青袍久零落，草堂灯火同驩谑。","别去依然三径荒，不堪罝兔堪罗雀。"]},{"t":"春日住尧峰山寺示瑞上人","f":"七言古诗","c":["谁谓东南山不高，尧峰之岭何岧峣。","等閒鹳雀飞不过，无数蛇龙卧自骄。","冥冥苍霭云树乱，风雷常走山之半。","黯惨岩扉昼不开，欹斜石磴危疑断。","凭陵眺瞩郁嵯峨，一起一伏山如波。","逶迤尽逐五湖去，琉璃盌内盛青螺。","振衣千仞寂不语，■然长啸应孤屿。","黄鹤仙人招不来，扁舟范蠡从兹去。","落落乾坤何不容，吴水吴山几万重。","此身不啻如一蚁，安能局蹐悲途穷。","头颅犹黑舌犹在，犹堪一日三千钟。","生儿宁尽如仲谋，马上何须羡乃公。","英雄事业流水尽，五陵荒草秋风紧。","世界浮生大梦中，空华倏忽看朝槿。","远公近借青莲室，猿猱麛鹿同招隐。","闭门满地白云流，风吹松花堕金粉。"]},{"t":"閒助甫参伯近有西秦之命喜而赋诗寄之","f":"古风","c":["海岱烟云开，仰见日月朗。","颇有高世心，悠然发远想。","明珠成霓玉成虹，不见萧敷与艾丛。","乍闻初拜凉州牧，乃是河南张长公。","向来不与人间事，消息传来喜不寐。","屹然独立有长城，何必秦关重百二。","丈夫高抱乐长征，瀚海天山渺去旌。","祁连大漠风雷色，疏勒飞泉金石声。","坐镇清风生朔野，三军尽爱宽裘者。","自是中朝山巨源，一麾出守看平蕃。","檄书不借陈琳草，游侠毋烦剧孟言。","独据羌床围细柳，朅来殊胜东山不。","黄石相逢知我心，苍生有待何能负。","昔时邂逅娄水边，琅琊甲第青云连。","读君新诗如入峡，绝壁腾波天倒悬。","我马玄黄饥且馑，何期一见称神骏。","价觅千金市与人，主非伯乐谁能信。","由是蹉跎一十春，萧萧双鬓半如银。","君今新得酒泉郡，应念东吴旧酒人。"]},{"t":"乔观察允德岁暮过访草堂连榻旬日漫成长句为别","f":"古风","c":["西风卷黄叶，堆压门之屏。","霜薄身上衣，冰厚爨下井。","偶有足音响空谷，枯桑惊散饥乌影。","君为岳牧久专城，朱衣烂漫黄金横。","何事萧然却车骑，独披鹤氅寻柴荆。","逍遥不减漆园吏，慰藉偏存瓮牖生。","幸有新醅共君醑，尚留木榻同爰处。","欲说荒斋如此寒，偶被风吹不能语。","陈家糠覈聊自肥，范叔绨袍竟谁与。","畴昔转输驾楼船，两年在君绣斧前。","汗血愿为伯乐用，心胆欲向干将悬。","不遣青蝇将玉毁，无奈薏苡如珠圆。","一歌雀角穿我屋，再歌黄鸟食我粟。","淮市曾为胯下行，灞陵屡止亭中宿。","莫将时命强干秦，吁嗟道路难于蜀。","羡君官爵良不卑，经纶献纳弩力为。","握手何当国士遇，拊髀谁动明王思。","酒酣别去泪如雨，生平敢负乔公知。"]},{"t":"弇山园逢沈嘉则席上见赠漫赋长句为答用纪兹会之盛","f":"古风","c":["西园汇才彦，主人陈思王。","式燕芙蓉池，言解翡翠裳。","坐临秋水弄皎月，澄觞飞盖生明光。","遂令花萼寄缃素，髣髴箫管遗琳琅。","后来盛事谁则同，弇园开在娄水东。","宾主曹刘日方驾，羽翼风雅何冲融。","何来四明有狂客，亦与七子相争雄。","萧然入林共把臂，便觉松下生清风。","杯酒相逢即定交，袖中投我以琼瑶。","漫试千言在倚马，独工五字能射雕。","山云恍披鹔鹴锦，池水忽涨桃花潮。","座有玉山多自欹，况复错落飞金卮。","高柯惊动灵鹊起，长川澹荡天河移。","后人艳说今日会，却如今视西园时。"]},{"t":"横塘逢钱功甫同泛湖上功甫作歌为赠率尔酬之","f":"古风","c":["横塘十里青山转，太湖秋水明如练。","菱歌才起眠鸥惊，蘋花尽落游鱼见。","兰叶浮来五两轻，葡萄一斛偏能盈。","缩项槎头银片阔，巨螯盘里珊瑚横。","船窗乱扑芙蓉绿，鸬鹚杓泛清于玉。","一歌杜甫渼陂行，再歌李白乌栖曲。","临流击楫烟云开，欲倾李杜平生怀。","相逢龊龊莫可语，眼中唯见钱生来。","钱生谓我才情丽，鹔鹴裘上春霞曳。","何为执戟风尘中，折腰十载青衫敝。","子言亹亹真慨慷，丈夫无泪沾衣裳。","湖波万顷峰七十，与子携手同翱翔。","楞伽精舍翠微里，松篁绕屋花盈几。","支郎却喜许询至，旋开香积醍醐美。","夕阳明灭水上飞，千山尽紫光湿衣。","空门旷寂且高卧，城郭偪促毋庸归。","君不见初月一痕五湖渺，馆娃镜里蛾眉巧。","又不见吴山落木秋风急，越来溪上戈船入。","僣王图霸倏一时，故宫荒寝千年思。","黍离麛鹿宛然在，夫差勾践争何为。","子怀和璧徒美好，我非石人不耐老。","歌凤狂言秖自嗤，雕虫小技安足道。","但须日饮三千钟，颓然醉倒万事空。","醒来孤岭发长啸，一声惊落天高鸿。"]},{"t":"阳山顾生愿甫赠我长歌颇过推与乃述怀志答","f":"古风","c":["男儿七尺期自爱，要令姓字千秋在。","不然草木与同腐，富贵纷华何足数。","吾家骠骑从文皇，赏延带砺山河长。","谁知后世贱介胄，虫沙猿鹤无低昂。","吾生久拼弃五斗，无奈嗷嗷啼八口。","身沾寸禄为人役，手持破斧门挂席。","逐队随行公府间，缁尘赤汗难为颜。","借人瘦马风吹倒，传家旧芾屋漏殷。","首如飞蓬色如土，傍人犹妒蛾眉妩。","以兹贝锦耀空幻，屏居寂寂南山涧。","阴符在匣羞与传，父书剩有毛苌编。","皎月流辉照白雪，飞泉疏越鸣朱弦。","虽然踉蹡人间弃，但言风雅心如醉。","乍来破产聊自放，青山啸傲常无恙。","江东复生顾虎头，自云痴绝无所求。","徙倚沧浪赓孺子，拍浮绿酒歌张侯。","贫交廿载真尔汝，何事长歌太称许。","谓我斯名堪不朽，敝帚千金良可丑。","吁嗟发短心则长，敦诗说礼聊自藏。","攀援今人身徒瘁，尚论古人口亦香。","君不见扬家子云老执戟，至今玄草光生白。","又不见湘累沉浮在鱼腹，世间离骚比珠玉。","毋论鹖士与波臣，日月文章万古新。","即今青鬓不弩力，辗转白发来侵人。"]},{"t":"寄宿田家偶述","f":"七言古诗","c":["西原夕照生平陆，东皋阴阴返樵牧。","夜行恐有醉尉呵，驱车且入田家宿。","田家老翁开柴门，拥彗不解犊鼻裈。","青山偏近新茅屋，绿酒那嫌旧瓦盆。","爨下一妇亦华发，豆萁乱束烹枯鳜。","团圞野坐不燃藜，短檐之下多明月。","自言门户无壮丁，数亩山田久不登。","近岁徵科猛于虎，几年蓄积消如冰。","闺中有女年十四，求鬻豪家气劳悴。","蛾眉换得金钱归，掌中空有明珠泪。","不记豪家谁姓名，此儿歌舞便教成。","婉媚自能当主爱，光华漫许倾人城。","前年寄采宜男草，曾遣苍头向吾道。","此中粱肉厌丘坻，忍令葵藿常不饱。","虽然儿女情自偏，不如聊且耕吾田。","以色事人岂常好，人间富贵浮云然。","闻之长啸斟大斗，仰见明河落高柳。","相逢良夜一论心，别去青溪重回首。"]},{"t":"送蒋邦士守备江藩","f":"古风","c":["君不见淮阴侯，绛灌为伍恒自羞。","又不见灌将军，武安怠骜若罔闻。","男儿七尺不易生，要令千载知其名。","吾今困处蓬蒿室，寸心烱烱无人识。","东邻少年何琐尾，西家老子生儿齿。","潦倒生平那可论，区区唯有蒋侯耳。","蒋侯能诵孙吴篇，猿臂善开五石弦。","从来未肯畏强禦，片言可以服文吏。","毕竟二千石，不揽卫尉权。","能作吴军气，终令赵璧全。","遂尔声名满人口，量移远驻江之右。","江头送别试雕弓，杨叶穿来当折柳。","西风吹落满地霜，晨驱匹马上河梁。","宝刀脱赠泣数行，英雄事业谁能当。","壮心寂寞何为乎，送君慷慨歌乌乌。"]},{"t":"送谢芝玉转饷北上","f":"古风","c":["谢侯年来半白头，何为又作燕京游。","张生久乏资身策，厌向人间送行客。","冰满关河雪满山，持觞欲饮风吹寒。","貂裘揽挈惨无语，叹息离人行路难。","年光寂寂流如电，愈见江河成世变。","君在行间三十年，由来吾辈人人贱。","丈夫所志在雄飞，安能雌伏情依依。","周王大发钜桥粟，伯夷甘守空山薇。","人各自有志，士也难再辱。","纵谓时乎肯复来，安能长受人羁束。","南山之趾北山头，白云片片还相留。","即看明世无真隐，何事秦时有故侯。","愿君不负青山约，且执牙筹算行橐。","黄金留作买山资，莫向长安乞官爵。","吾先蹑屩深山中，君归定访山人踪。","看君白发增几许，抚掌大笑沧溟空。"]},{"t":"尧峰山清晖轩落成送楞伽寺弘上人归隐且见余志","f":"七言古诗","c":["尧峰古刹连翠微，黄茅盖殿白板扉。","鸟窠蟒窟僧住少，秖馀山水含清晖。","楞伽山中大弟子，偶来飞锡披荆枳。","石头路滑雪纷纷，却遇庞家老居士。","相期岩下种青莲，懒乞人间造业钱。","无金布地不著想，有珠系衣且自捐。","一袈裟地无十笏，绵蕞草构为禅室。","松麈蒲团日日閒，黄花翠竹纤纤出。","本来无住亦无生，究竟何能识净因。","且将清澈宝云井，作供灯光华鬘身。","涧底流泉鸣不止，峰头朗月恒如此。","蝴蝶浮生梦已醒，莲花事业心如水。","般若慈航咫尺间，菩提高树岂难攀。","愿留白足常为伴，未许黄梅便出山。"]},{"t":"客舍答顾愿甫","f":"七言古诗","c":["燕京八月青霜飞，秦庭客子悲无衣。","千里故人一书札，问我式微何不归。","驰驱失路汗无血，纵横计尽徒存舌。","三秋雨散金错囊，十年苔绣芙蓉铁。","但愿铩羽归故山，将雏栖息藩篱间。","仰看吾国有大鸟，飞鸣有意惊人寰。"]},{"t":"初春与客即事","f":"七言古诗","c":["霏微细雨生湖滨，门前柳色朝朝新。","芳草能留远游客，黄鹂似报江南春。","杏子花开好颜色，施朱著粉谁为饰。","嫣然疑是东家妹，乍来窥我墙头立。","似与东风旧有情，相逢沽酒阖闾城。","婆娑且就垆头醉，慷慨谁论世上名。"]},{"t":"喜谢侯相过","f":"七言古诗","c":["夫差城中车与马，扬扬谁识衡门下。","安石能来问许询，相逢绝少元规尘。","直钩共把沧浪钓，开口且向青天啸。","东邻杏花方嫣然，柳条才可胜春烟。","床头禄米储一斛，换酒堪直三千钱。"]},{"t":"寒食限韵作","f":"七言古诗","c":["阖闾风土不禁火，绿水城边碧油舸。","屡逢蹴鞠踏花茵，时见鞦韆乱云朵。","金莲点点步底生，鸳鸯彩彩缠头亸。","越女曾为吴馆娃，周郎只合留江左。","前溪桃树隔垂杨，髣髴红妆隐青琐。"]},{"t":"枫桥与送者别","f":"七言律诗","c":["枫桥秋水绿无涯，枫叶满树红于花。","万里之行才十里，阖闾城头尚堪指。","游子尊前泪湿衣，离心已逐片帆飞。","酒酣不识身为客，意欲元同送者归。"]},{"t":"扬州春眺即事","f":"七言律诗","c":["紫萸村边扬子湾，黄公垆头使者关。","舟楫远通淮北水，楼台近见江南山。","高冈百尺临官渡，浮烟不尽斜阳暮。","前朝杨柳几株存，寒鸦飞尽芜城路。"]},{"t":"客堂秋夕","f":"七言律诗","c":["高梧百尺入云凉，清水一池生月光。","秋夜初长客不寐，坐听砧声思故乡。","明河辗转天欲曙，寒螀唧唧犹自语。","挈衣起写故乡书，明日关河雁南去。"]},{"t":"新丰主人","f":"七言律诗","c":["新丰主人邯郸妇，依然卖酒三河口。","芬芳芍药气如兰，潋滟葡萄绿于柳。","东风日日飞轻尘，游子年年只问津。","迟回立马门前客，曾是垆头醉卧人。"]},{"t":"郊祀伏睹驾出二首 其一","f":"五言律诗","c":["驰道千官集，缇城百帐分。","天行清跸雨，山出护宫云。","辇毂龙真见，旌麾凤有文。","此中骖乘者，应是霍将军。"]},{"t":"郊祀伏睹驾出二首 其二","f":"五言律诗","c":["上帝歆元祀，南郊启閟宫。","幸逢尧丽日，仰见舜重瞳。","仙乐闻难尽，霓旌望不穷。","材官多侍从，偏我隐墙东。"]},{"t":"春日游西苑二首 其一","f":"五言律诗","c":["宣室临西苑，灵台对籍田。","宫莺迷绿雨，厩马饮清川。","柳引金堤直，松含玉殿圆。","先皇受釐处，寂寞锁春烟。"]},{"t":"春日游西苑二首 其二","f":"五言律诗","c":["禁云流不尽，苑树碧丛丛。","水浅鸳鸯岛，花深翡翠宫。","引泉珠错落，叠石玉玲珑。","莫认桃源路，银河岂易通。"]},{"t":"部饷至京引见皇极门时戊辰九月五日二首 其一","f":"五言律诗","c":["玉几星垂拱，金门旭始开。","夔龙端简侍，扬马执经来。","灵曜瞻难定，神飙瞩易回。","进呈盐铁论，付与度支裁。"]},{"t":"部饷至京引见皇极门时戊辰九月五日二首 其二","f":"五言律诗","c":["云日散高秋，钟鸣五凤楼。","面君今日喜，在野十年忧。","下走惭簪绂，前驱愧蒯缑。","无能驯鹿性，终尔怯螭头。"]},{"t":"引见赐宴恭纪二首 其一","f":"五言律诗","c":["天语传闻近，山呼引拜遐。","鸿胪跽承旨，光禄立开衙。","白粲分阶玉，黄流借殿霞。","彻归成独享，此际益思家。"]},{"t":"引见赐宴恭纪二首 其二","f":"五言律诗","c":["重漕明主意，既醉远臣心。","席避彤庭日，筵依松树阴。","大官多且旨，小史酌还斟。","世食天朝粟，衔恩岂自今。"]},{"t":"长安春望二首 其一","f":"五言律诗","c":["莺花鸣凤晓，钟鼓濯龙开。","湛露仙人掌，晴云日观台。","河将银汉去，山向玉宸来。","辇下阳春曲，能容骑尉裁。"]},{"t":"长安春望二首 其二","f":"五言律诗","c":["太和盈宇宙，烂漫遍光华。","美丽都人绮，芳菲辇道沙。","紫骝衔禁草，黄鸟卧宫花。","一望千重殿，常生五色霞。"]},{"t":"长安街伏睹庄皇帝梓宫归山陵二首 其一","f":"五言律诗","c":["虎贲趋上将，龙驭从群仙。","■幕灵芝盖，祠坛瑞玉筵。","进贤冠未毁，斩佞剑犹悬。","帝子真纯孝，冲年泪似泉。"]},{"t":"长安街伏睹庄皇帝梓宫归山陵二首 其二","f":"五言律诗","c":["薤露盈驰道，臣民候挽齐。","山河俄改色，草树尽含凄。","象卫过金马，刍灵出碧鸡。","有髯攀不及，怅望鼎湖西。"]},{"t":"朝皇极殿颁万历改元历时壬申十月朔二首 其一","f":"五言律诗","c":["凤凰栖沼上，鳷鹊朗云中。","周室方全盛，成王在幼冲。","休徵方出洛，天寿尽呼嵩。","卜历元无算，编年万未穷。"]},{"t":"朝皇极殿颁万历改元历时壬申十月朔二首 其二","f":"五言律诗","c":["湛露收青汉，云韶出紫宸。","颁来一统历，散去万家春。","宣室重禧肇，明堂受命新。","世臣唯饱饭，常作太平人。"]},{"t":"观象台看雪二首 其一","f":"五言律诗","c":["人间寒逾切，天上瑞先呈。","不辨黄金屋，唯看白玉京。","风花连汉畤，冰叶满秦城。","此日观乾象，璇玑分外明。"]},{"t":"观象台看雪二首 其二","f":"五言律诗","c":["铜龙高失翠，玉尺旋生华。","星宿灵妃府，琼瑶帝子家。","光留长信月，影乱上林花。","一望银潢接，寻源未有槎。"]},{"t":"席上呈申太史二首 其一","f":"五言律诗","c":["几席留明月，花枝带禁烟。","酒醲分玉醴，烛短剩金莲。","史是迁之后，文如汉以前。","且辞长夜饮，蚤起从甘泉。"]},{"t":"席上呈申太史二首 其二","f":"五言律诗","c":["夹道通仙署，清槐无世尘。","寂寥桑梓客，参对草麻人。","露掌铜龙近，天颜金马亲。","治安垂万世，公等绾丝纶。"]},{"t":"访胡原荆侍御","f":"五言律诗","c":["相逢宣武第，暂解惠文冠。","清泪长安尽，秋霜短鬓残。","栖乌纤月落，鸣凤上阳寒。","圣政元无阙，封章莫浪弹。"]},{"t":"饮冯杜二使君","f":"五言律诗","c":["暂罢金銮直，来为鸡黍期。","大冯元补阙，小杜亦分司。","谏草防人见，觥筹任客私。","故园凋落尽，不是在家时。"]},{"t":"赠晋陵王太学二首 其一","f":"五言律诗","c":["五侯千日醉，七贵一家亲。","避地依京洛，愁身浪笑嚬。","青衣歌宛转，白眼看沉沦。","何似金门客，嗟嗟叹积薪。"]},{"t":"赠晋陵王太学二首 其二","f":"五言律诗","c":["羡尔遨游美，何知旅食艰。","长杨驰马去，芳草踏歌还。","久住唯金谷，常颓是玉山。","燕姬新买得，江上杏花颜。"]},{"t":"潞河中秋初度二首 其一","f":"五言律诗","c":["问年逢六六，逆旅自茕茕。","白发须臾事，黄金乌有生。","据鞍宁待试，邀笛不辞行。","愁绝今宵月，重圆蓟北城。"]},{"t":"潞河中秋初度二首 其二","f":"五言律诗","c":["桂影青天满，桑乾白水斜。","公车不待诏，客舍秪思家。","报主雌雄剑，谋生子母瓜。","去年今夜酒，吴市听琵琶。"]},{"t":"广福寺寓二首 其一","f":"五言律诗","c":["不梦麒麟阁，皈依孔雀王。","蒲团閒里过，药裹定中忘。","宴坐霞餐晚，清言水观凉。","空门无一事，养就懒嵇康。"]},{"t":"广福寺寓二首 其二","f":"五言律诗","c":["白璧空投路，青山且息机。","隙驹怜促影，怖鸽倦雄飞。","迹许畸人识，心甘静者依。","尘襟方欲浣，暂借水田衣。"]},{"t":"送原荆归田二首 其一","f":"五言律诗","c":["敢言身讵惜，怅别袂难分。","徒步燕山雪，悲歌易水云。","纲常一疏见，恸哭两宫闻。","不遣长沙去，君恩厚汉文。"]},{"t":"送原荆归田二首 其二","f":"五言律诗","c":["大戆微臣罪，馀生圣主留。","迟回方出昼，黯澹似悲秋。","妻子谙田作，亲朋仰岁收。","青青桓氏马，不见玉街游。"]},{"t":"醉宿幼元寓二首 其一","f":"五言律诗","c":["方朔栖金马，文园卧锦茵。","远携阳羡秫，乍酿洞庭春。","红树摇歌扇，青衣动舞尘。","沉酣自吾党，休沐肯嫌频。"]},{"t":"醉宿幼元寓二首 其二","f":"五言律诗","c":["为欢常卜夜，不厌酒淋漓。","湿尔凤毛好，濡吾燕颔奇。","放歌惊宿鸟，深坐待朝曦。","却洗何人事，高阳郦食其。"]},{"t":"送朱在明使楚","f":"五言律诗","c":["十里河梁暮，天寒送子迟。","冰坚车乱度，雪厚路多疑。","大别江平掌，九疑山画眉。","长沙衔使命，莫作逐臣悲。"]},{"t":"同幼元饮光禄署","f":"五言律诗","c":["纵饮防人见，盘餐窃自传。","黄流银海注，翠釜玉绳悬。","柳外君庖迥，花间仙署连。","大珰来络绎，臂以绿韝缠。"]},{"t":"潞河雪二首 其一","f":"五言律诗","c":["十月燕山雪，孤舟潞水涯。","沙滩银浪细，岸柳玉条斜。","逐鹭宁分羽，栖芦欲混花。","蓬窗莫令进，易惹鬓生华。"]},{"t":"潞河雪二首 其二","f":"五言律诗","c":["雪霰今朝集，寒冰昨夜坚。","幸存东郭履，不赋北门篇。","客路黄云外，乡书白雁边。","关河无锁钥，偏阻未归船。"]},{"t":"塞下二首 其一","f":"五言律诗","c":["都护称飞将，提兵禦犬戎。","楚弓斜抱月，边马竞追风。","魏绛和无议，秦开战有功。","黄金新铸印，擎出大明宫。"]},{"t":"塞下二首 其二","f":"五言律诗","c":["乘鄣蛮云白，行营汉月新。","回中牧马地，句注引弓民。","傍夏不消雪，入关才有春。","天王大一统，冒顿久称臣。"]},{"t":"少年二首 其一","f":"五言律诗","c":["长杨驰马去，平乐斗鸡回。","婉媚贝为带，欢娱金作罍。","横行羡田窦，侍从陋邹枚。","不惜耽荒宴，朱颜良易摧。"]},{"t":"少年二首 其二","f":"五言律诗","c":["桃李芳菲候，流苏春帐悬。","文君侍琴瑟，太主发金钱。","玉具芙蓉剑，银装玛瑙鞭。","单车花底散，人望俨如仙。"]},{"t":"折柳","f":"五言律诗","c":["三春杨柳绿，一望泪潸潸。","匹马此曾系，长条忍再攀。","翠凋愁里鬓，红减别时颜。","风絮轻千里，将心度玉关。"]},{"t":"边月","f":"五言律诗","c":["半轮升古塞，长剑度河堤。","绕碛黄狐穴，连沙白雁栖。","军声传蓟北，霜色满辽西。","此际征人泪，应同少妇啼。"]},{"t":"闺思二首 其一","f":"五言律诗","c":["夫婿萧关外，音书寂不闻。","朝朝江上石，夜夜枕边云。","鸾镜元羞妾，蛾眉好待君。","还将丝一寸，绣作锦回文。"]},{"t":"闺思二首 其二","f":"五言律诗","c":["夜梦空飞远，朝心郁不开。","宝钗寒翠羽，瑶瑟长青苔。","花瓣粘蜂去，晴丝罥燕来。","前鱼无暇泣，别鹤恨难裁。"]},{"t":"薄命","f":"五言律诗","c":["三载食君贫，严霜六月侵。","但能留一剑，何惜抱孤衾。","镜里花如貌，人间石比心。","羞他机下妇，含笑为黄金。"]},{"t":"青楼","f":"五言律诗","c":["女郎能任侠，结客少年时。","容颜市金币，肝胆刺恩私。","密约来原剧，穷交自扊扅。","信陵归魏后，何以报如姬。"]},{"t":"春宴二首 其一","f":"五言律诗","c":["燕寝氍毹榻，雕盘涧沚毛。","将军青最幸，词客白犹豪。","华月高梧影，冰弦流水操。","两行红粉在，谁是郑樱桃。"]},{"t":"春宴二首 其二","f":"五言律诗","c":["锦屏开子夜，珠履集春申。","诮凤非无客，图麟合有人。","樽前摇白羽，花下卧朱轮。","妙舞清歌后，幽怀可具陈。"]},{"t":"寺居二首 其一","f":"五言律诗","c":["穴处聊同蚁，巢居反借鸠。","偶来依净土，常自对沧洲。","云乱竹间度，泉分花下流。","未须论出世，吾自乞吾休。"]},{"t":"寺居二首 其二","f":"五言律诗","c":["未定去来意，其如生灭何。","舍身能忍辱，听法可降魔。","白日一僧语，青天双鸟过。","悠然会心处，潭影印松萝。"]},{"t":"赠客","f":"五言律诗","c":["明时难自见，牢落不羁才。","富贵浮云耳，乾坤传舍哉。","宁忧塞马失，呼得野鹰来。","王粲愁亡赖，同登江上台。"]},{"t":"社日","f":"五言律诗","c":["春社散柴桑，迟回度石梁。","饭牛嗟百里，割肉笑东方。","细雨青山湿，桃花流水香。","野鸥浑狎我，飞近扑衣裳。"]},{"t":"偶成二首 其一","f":"五言律诗","c":["家贫常罢尉，身懒似逃名。","繁弱提偏重，岑牟著更轻。","柳疏莺晚逗，花落蝶先迎。","食肉非吾分，持螯过此生。"]},{"t":"偶成二首 其二","f":"五言律诗","c":["不乐区中偪，言从方外游。","人嘲安用解，客难曷为酬。","贝叶经三藏，莲花酒一瓯。","生涯问流水，天地竟虚舟。"]},{"t":"访客","f":"五言律诗","c":["故人金马客，消渴卧文园。","岸帻高梧影，援琴流水言。","竹篱黄蝶乱，野荠白花繁。","枳棘中原在，毋脂日暮辕。"]},{"t":"旅思","f":"五言律诗","c":["不尽桑乾水，潺潺浸月寒。","关山悲短笛，儿女忆长安。","秋半青蘋老，霜前白苧单。","南归多雁影，欲寄一书难。"]},{"t":"饮顾从化","f":"五言律诗","c":["已分时才晚，唯凭杯酒深。","五经堪弃掷，一第尚浮沉。","种种悲吾发，青青惜子衿。","蛾眉羞再画，无奈入宫心。"]},{"t":"济上逢张漕尉","f":"五言律诗","c":["济水绕船流，萧然独树秋。","暮云停楚骑，明月出吴钩。","主计张苍棹，沉酣李白楼。","不堪思往事，零落半同游。"]},{"t":"送楚客之越","f":"五言律诗","c":["京洛一为别，念君多苦辛。","啼猿常送客，归雁远逢人。","十载辞江夏，千山过富春。","匣中雄剑在，拂拭气还新。"]},{"t":"别广福进公","f":"五言律诗","c":["汤休能惜别，相送出精蓝。","水长陂全没，云低雨半含。","不堪宁止七，见黜欲过三。","此日人犹北，惊看雁已南。"]},{"t":"有感","f":"五言律诗","c":["风尘犹道路，湖海自浮沉。","浪说交张耳，何人识季心。","霜留三尺剑，星散一囊金。","落落飞腾志，空知返故林。"]},{"t":"寒食","f":"五言律诗","c":["旅食怅犹寒，春愁匹马间。","山河壮燕赵，风土忆荆蛮。","驿路桃花落，乡心燕子还。","饧糕尝未敢，千里隔慈颜。"]},{"t":"饮子念新斋二首 其一","f":"五言律诗","c":["野服都裁芰，儒宫半艺兰。","莺花春有约，鸡黍晚留欢。","种药乘膏雨，栽松伴岁寒。","绝怜俱老大，萧索竹皮冠。"]},{"t":"饮子念新斋二首 其二","f":"五言律诗","c":["蓬径閒堪扫，山窗卧亦坚。","蛾眉为世弃，鸡口漫人前。","北海刺常灭，南州榻屡悬。","竹林多酒伴，秖赏步兵贤。"]},{"t":"江楼","f":"五言律诗","c":["高阁凭扬子，登临伤客心。","云青山有色，潮白海生音。","落日灵均庙，秋风庄舄吟。","大江南去路，惆怅暮归禽。"]},{"t":"山居","f":"五言律诗","c":["一室蓬蒿翳，悠然紫翠深。","凉飔起松上，夕照出花阴。","流水沉冥意，空山久住心。","寥寥问孤鹤，千载孰知音。"]},{"t":"西山访叔平丈二首 其一","f":"五言律诗","c":["耆旧寻庞德，西畴扣绿扉。","开樽燕子到，点笔杏花飞。","独鹤寻鱼穴，孤松挂薜衣。","从游多鹿豕，久矣故人希。"]},{"t":"西山访叔平丈二首 其二","f":"五言律诗","c":["清言聊共晤，白发竟忘愁。","柳暗门常闭，花飞村自幽。","存交怜故尉，往役见诸侯。","浊酒时相慰，山田薄有收。"]},{"t":"与谢都尉山游二首 其一","f":"五言律诗","c":["山水逢皆胜，冠裳见自疏。","白莲同结社，黄石未传书。","东郭贫非病，西林樵可渔。","为君容借屐，不问出无舆。"]},{"t":"与谢都尉山游二首 其二","f":"五言律诗","c":["湖海能容我，微官安事哉。","先朝存带砺，今日置寒灰。","要妓歌秾李，寻僧吹落梅。","差强投笔吏，不得玉关回。"]},{"t":"琅琊别墅二首 其一","f":"五言律诗","c":["高阁临花渚，云英逐望新。","空濛微见海，窈窕曲藏春。","乔木元无恙，青山已即真。","君家旧时墅，曾住两珣珉。"]},{"t":"琅琊别墅二首 其二","f":"五言律诗","c":["邻刹松涛远，隔川花雨轻。","云峰分太华，池水半昆明。","浮白消尘虑，耽玄匪世情。","超然得禅悟，园以小祇名。"]},{"t":"幽居","f":"五言律诗","c":["烟霞元自癖，寤寐向谁论。","净业莲为社，青山鹿应门。","暂留徐孺子，深避窦王孙。","为语冥冥雁，中原矰弋繁。"]},{"t":"饯客","f":"五言律诗","c":["细雨孝廉棹，经过芳草城。","渚云飞不尽，山月正初生。","白帢谈名理，清樽惜别情。","如逢燕赵客，为报厌纵横。"]},{"t":"赠子念二首 其一","f":"五言律诗","c":["吾自识曹丘，同为长者游。","下帷虚董策，借箸竟良筹。","清圣元无羡，情痴卒未休。","花间呼小友，张绪最风流。"]},{"t":"赠子念二首 其二","f":"五言律诗","c":["谢傅爱羊昙，东山日并骖。","称名当第五，受爵敢过三。","浪谑曾无虐，风骚秖自耽。","庭花莫閒种，芳草树宜男。"]},{"t":"濠上逢客","f":"五言律诗","c":["相逢木兰棹，同过渚莲亭。","散发新添白，看山不改青。","种花无旧业，视草有玄经。","寂寞江湖上，常占处士星。"]},{"t":"送客之滇","f":"五言律诗","c":["始遂四方志，何知万里长。","雪消犹故国，草绿已他乡。","旅鬓欲垂白，行囊尽点苍。","巴江元学字，不阻校书航。"]},{"t":"访顾朗","f":"五言律诗","c":["野径莽无迹，山园摽有梅。","客能骑马到，主自饭牛回。","藉草深趺坐，临花浅送杯。","狂生今尔汝，清话总成诙。"]},{"t":"逢王承父","f":"五言律诗","c":["苇叶梁溪舫，蘋花秋水风。","两人斗酒共，千古寸心同。","诗是山东白，才非吴下蒙。","词坛分赤帜，吾党小英雄。"]},{"t":"同卫僚游虎丘","f":"五言律诗","c":["彻侯戎理暇，小队出城西。","金勒材官鞚，银瓶健卒提。","云根堪试剑，兰叶亦然犀。","为作军中乐，林莺不敢啼。"]},{"t":"过郑丞","f":"五言律诗","c":["郑公门似水，杨柳绿如丝。","自哂官阶小，那嫌堂构卑。","飞花竟亡赖，归燕不愆期。","投辖人皆醉，毋烦置驿为。"]},{"t":"端午二首 其一","f":"五言律诗","c":["风雨淹佳节，搴裳独采蒲。","久无观妓咏，近有辟兵符。","竹径留中散，江流忆左徒。","乾坤自拘碍，吾意只菰芦。"]},{"t":"端午二首 其二","f":"五言律诗","c":["角黍绿离离，茶瓜与客期。","短衣悬艾艾，长命续丝丝。","燕乳过初夏，蜂喧恰午时。","葵榴幸无恙，折取伴芳卮。"]},{"t":"遇京口程秀才因寄朱将军","f":"五言律诗","c":["羽檄关河静，风尘客路分。","相逢伯休父，因忆季将军。","组练长江雪，旌旗建业云。","还应赋秋兴，不草出师文。"]},{"t":"客夜","f":"五言律诗","c":["剑锋消不尽，一室欲飞霜。","孤戍猿声里，高城鸟道傍。","风尘存季布，肝胆借田光。","我马玄黄色，伤心去路长。"]},{"t":"家信","f":"五言律诗","c":["雁高呼不下，凭汝报平安。","作客年年别，为官事事难。","黑貂孤泪夜，白发一丝寒。","愁绝江南信，梅花雪后残。"]},{"t":"卷六 出塞二首 其一","f":"五言律诗","c":["赤帜空邻壁，朱麾满汉营。","受降当夜半，飞捷入春明。","赐锦麟裁就，悬金鹊化成。","玺书频慰劳，天子重干城。"]},{"t":"卷六 其二","f":"五言律诗","c":["列骑猎飞狐，龙城出虎符。","宝刀寒太白，绣甲卷天吴。","都尉称强弩，将军字破奴。","控弦三十万，踊跃取休屠。"]},{"t":"侠客二首 其一","f":"五言律诗","c":["六郡连三辅，秦城接楚疆。","无非游侠地，总是少年场。","万户片言得，千金一掷亡。","青楼多艳妇，虽老觅徐娘。"]},{"t":"侠客二首 其二","f":"五言律诗","c":["平生未识愁，出入富平侯。","彊灌令人釂，居间倩客筹。","乘黄千里驷，狐白万金裘。","厌说雕虫技，梁园只浪游。"]},{"t":"陇水","f":"五言律诗","c":["陇水陇头清，氐羌陇下营。","不堪刁斗乱，况复夜猿鸣。","转战黄云合，寻源白发生。","月明边籁静，肠断此中声。"]},{"t":"落梅","f":"五言律诗","c":["清夜梅花落，冰霜行路难。","金微残梦绕，玉篴一声寒。","马上凭谁寄，闺中只独看。","忽流明月影，双泪湿阑干。"]},{"t":"婕妤","f":"五言律诗","c":["长信悬孤月，增成愁望中。","身轻不如燕，那敢怨东风。","流水朱弦断，飞花舞袖空。","还将辞辇意，随分处深宫。"]},{"t":"明妃","f":"五言律诗","c":["单于愿称婿，宫女出良家。","犀带黄金饰，旃裘白雪花。","照来犹汉月，看去已胡沙。","握发羞明镜，飞蓬恨未华。"]},{"t":"忆别","f":"五言律诗","c":["别去弥年载，容华异昔时。","镜分残两月，弦断散千丝。","雨泪含花脸，春愁结柳眉。","归期聊出卜，多露晓行迟。"]},{"t":"堤柳","f":"五言律诗","c":["大堤千树柳，尽是故倡家。","憨态向谁好，柔枝空复斜。","掌中身似燕，钗畔髻如鸦。","遮莫思张绪，无心折杏花。"]},{"t":"从军二首 其一","f":"五言律诗","c":["结发事戈矛，新从定远侯。","横行非面谩，感激许身酬。","烽火消雄剑，燕姬脱战韝。","军中无饮器，好借月支头。"]},{"t":"从军二首 其二","f":"五言律诗","c":["仗钺出甘泉，将军秋备边。","骍弓善猿臂，凤铠称鸢肩。","结客通中贵，擒王得左贤。","功名陋田窦，麟阁许谁先。"]},{"t":"铜雀","f":"五言律诗","c":["奉寝传遗教，留欢觅故心。","梦为云雨薄，恩向死生深。","解犹纤玉，香分剩郁金。","可堪漳水月，夜夜照孤衾。"]},{"t":"芳树","f":"五言律诗","c":["芳树映窗纱，容华散早霞。","临妆恐生妒，搴幔故相遮。","欲结同心子，先开并蒂花。","东风莫吹落，夫婿恰还家。"]},{"t":"湖上宴集二首 其一","f":"五言律诗","c":["桂楫出横塘，兰陵绿酒香。","露桃无赖色，夜月可怜光。","客赋元鹦鹉，山名是凤凰。","江南风物丽，罗绮俨成行。"]},{"t":"湖上宴集二首 其二","f":"五言律诗","c":["使者解金龟，春风倒接䍦。","柳丝缫燕子，花瓣掠鱼儿。","水绿平铺绮，山青远画眉。","落梅新制曲，红袖隔船吹。"]},{"t":"朗上人林泉二首 其一","f":"五言律诗","c":["筑室栖支遁，为园象给孤。","流泉动朱瑟，松露落明珠。","施食山禽睨，翻经野鹿趺。","言寻许玄度，先遣具醍醐。"]},{"t":"朗上人林泉二首 其二","f":"五言律诗","c":["古木藏精舍，春风日闭关。","飞花自容与，乳燕任游閒。","禅影清池上，经声绿竹间。","何须携锡远，自有赤城山。"]},{"t":"郊外","f":"五言律诗","c":["野望晓苍苍，川原喜载阳。","云飞山动影，露湿草生光。","柳下寻元亮，花间遇仲长。","携来一壶酒，开与故人尝。"]},{"t":"友人新斋","f":"五言律诗","c":["草构方除旧，蓬门今始开。","春衣黄似柳，岁酒碧于苔。","野水从傍引，山花取次栽。","孔融新第宅，张俭又轻来。"]},{"t":"观猎","f":"五言律诗","c":["都护班师日，龙城会猎齐。","兔藏鹰侧目，鹿失马穿蹄。","诡遇元干律，偏师亦自提。","擒生市斗酒，明月灞陵西。"]},{"t":"朱楼","f":"五言律诗","c":["结绮兰芬散，临春环佩鸣。","黄金寿爰叔，绿酒醉陈卿。","隐几三眠柳，迷花百啭莺。","朱楼巢翡翠，燕子陋为名。"]},{"t":"同黎徐二帅游南屏山二首 其一","f":"五言律诗","c":["并骑骅骝美，芳郊桃李秾。","酒光明琥珀，山色秀芙蓉。","卫霍春多暇，邹枚日过从。","材官俱乐凯，饮至奏歌钟。"]},{"t":"同黎徐二帅游南屏山二首 其二","f":"五言律诗","c":["柳下对呼卢，朱丝系玉壶。","绮罗临水乱，鼓吹入云无。","红杏村村雨，青山处处湖。","步兵良酝具，不问酒家胡。"]},{"t":"春闺二首 其一","f":"五言律诗","c":["罗袖裁全疋，轻盈出桂房。","柳眉莺睥睨，花靥蝶颠狂。","夜月求凰调，春风堕马妆。","良人知未返，较猎入长杨。"]},{"t":"春闺二首 其二","f":"五言律诗","c":["应识娇亡赖，悬知态尽憨。","采芳非怨女，带草是宜男。","窥玉全生妒，留髡半倚酣。","无凭云雨梦，都使寸心含。"]},{"t":"晚步二首 其一","f":"五言律诗","c":["偶来寻野寺，忽复过柴桑。","听鸟竹林下，逢僧流水傍。","绿云生麦陇，斜日上鱼梁。","嵇阮时相问，黄公尚卖浆。"]},{"t":"晚步二首 其二","f":"五言律诗","c":["楚客混渔樵，清溪散步遥。","涧藤栖暝翠，山磬韵春潮。","野兴花能引，羁魂酒可招。","久无瓯冶佩，常挂许由瓢。"]},{"t":"岣嵝山居二首 其一","f":"五言律诗","c":["岩扉对灵隐，山阁启清晖。","水浅溪如剡，花深曲似韦。","触人香麝过，背客锦禽归。","飞瀑飘晴雪，泠泠湿我衣。"]},{"t":"岣嵝山居二首 其二","f":"五言律诗","c":["窈窕桃源路，渔樵只浪猜。","巢居同幻住，峰影逼飞来。","乌几云流湿，黄庭风展开。","彼将身隐矣，吾岂避秦哉。"]},{"t":"赠阮都尉二首 其一","f":"五言律诗","c":["砥砺收民誉，吹嘘借士评。","一官成皓首，五字擅长城。","对月吴钩跃，临风越甲鸣。","汉庭徵老将，犹可代专征。"]},{"t":"赠阮都尉二首 其二","f":"五言律诗","c":["南阮贫如昨，步兵犹可怜。","吁嗟威武士，寂寞广文毡。","幸有官厨酒，曾无负郭田。","建安多丽藻，谁在咏怀前。"]},{"t":"园居二首 其一","f":"五言律诗","c":["种柳门初绿，浣花堂亦深。","秖将投笔意，不负灌园心。","独抱庐中膝，时操弦外琴。","翻嫌扣角者，飒飒动商吟。"]},{"t":"园居二首 其二","f":"五言律诗","c":["买得钓鱼矶，依然昼掩扉。","小窗摊蠹简，斜日晒牛衣。","亭子乌皮几，山妻白苧机。","柴桑不开径，彭泽敢言归。"]},{"t":"晏坐二首 其一","f":"五言律诗","c":["日接林中侣，时来方外群。","楚山隐几见，羌笛卷帘闻。","绿树啼黄鸟，青天流白云。","北窗閒悦绎，柱下五千文。"]},{"t":"晏坐二首 其二","f":"五言律诗","c":["挥麈青松净，披衣白苧轻。","断霞归屿迥，纤月堕江明。","清啸嵇中散，沉酣阮步兵。","何知身世促，咄咄但谋生。"]},{"t":"广陵遇客","f":"五言律诗","c":["敝裘仍岁月，短棹只菰芦。","歌凤身留楚，负薪家在吴。","仓庚三月雨，平仲一城芜。","零落东西去，高阳旧酒徒。"]},{"t":"彭城","f":"五言律诗","c":["去国久为客，思家更属秋。","鲛人月中泪，燕子水边楼。","绿树帆飞度，青山云乱流。","可堪张仲蔚，借住李膺舟。"]},{"t":"鲁桥","f":"五言律诗","c":["凫绎青岚近，龟蒙黛色连。","看山浑不厌，把酒正相便。","津树常遮月，沙滩少住船。","平生击楫志，都付卜居篇。"]},{"t":"过王文学","f":"五言律诗","c":["作客三千里，为儒一亩宫。","蛛丝缫户上，鸟迹篆沙中。","解佩湘皋共，藏书邺架同。","沉沦何必叹，著述起王通。"]},{"t":"魏季朗贡入太学寄赠二首 其一","f":"五言律诗","c":["驱车随计吏，杖策度黄河。","岳色凌空下，云英夹日过。","梦悬金马隔，路出碧鸡讹。","千古豪雄事，居然限制科。"]},{"t":"魏季朗贡入太学寄赠二首 其二","f":"五言律诗","c":["握中神物在，沦落世犹惊。","照乘三光失，支机五采生。","解颐周列国，抵掌汉西京。","若说雕虫技，翻令意不平。"]},{"t":"金陵徐园宴集分得壶字二首 其一","f":"五言律诗","c":["卢橘园千顷，葡萄酒百壶。","溪声来远瀑，云影曳流苏。","花落纷迎蝶，萍流曲引凫。","主人能好客，当代执金吾。"]},{"t":"金陵徐园宴集分得壶字二首 其二","f":"五言律诗","c":["凤凰犹馆榭，朱雀半蘼芜。","公子元封魏，佳人本姓卢。","云霄开甲第，歌舞出名都。","不羡金为埒，唯怜玉作壶。"]},{"t":"晦迹","f":"五言律诗","c":["清时真自失，世路岂相援。","晦迹蠖同屈，雄谈虱屡扪。","绨袍存国士，脱粟进王孙。","执戟艰危在，秋霜拂泪痕。"]},{"t":"漫兴","f":"五言律诗","c":["欲移愚谷住，乞得醉乡封。","久自甘人弃，难为悦已容。","时情轻马走，世态厌龙钟。","落落沉冥者，吾师阮嗣宗。"]},{"t":"清郡访郑丈二首 其一","f":"五言律诗","c":["处士芰荷裳，相将舞媚娘。","竹枝新度曲，桃叶旧怜香。","碧椀银丝鲙，冰壶白玉浆。","清泉自销暑，落月尚飞觞。"]},{"t":"清郡访郑丈二首 其二","f":"五言律诗","c":["白首美遨游，他乡行乐稠。","朱弦被琴瑟，绿树系骅骝。","虚席迎无忌，倾囊问莫愁。","每劳银不律，只为锦缠头。"]},{"t":"清郡大宁寺二首 其一","f":"五言律诗","c":["借住元常住，深藏是善藏。","注瓶泉水冷，开卷法华香。","古桧如虬偃，新松比鹤长。","红尘将赤日，亦避寺清凉。"]},{"t":"清郡大宁寺二首 其二","f":"五言律诗","c":["初地能逃暑，中宵暂问禅。","草中生熠耀，藕上吐婵娟。","同舍病摩诘，东邻老郑虔。","吁嗟坎壈岁，忏悔佛灯前。"]},{"t":"兖州晓行","f":"五言律诗","c":["残月照征衣，村荒人住希。","三星犹耿耿，四牡正騑騑。","岱翠云中落，霜华剑上飞。","经过获麟处，吾道泪堪挥。"]},{"t":"沙河道中","f":"五言律诗","c":["洲渚河流剩，沙堆风卷馀。","牛羊纷认牧，禾黍乱成畬。","枣熟人憎鸟，荷枯獭趁鱼。","秋霜欲侵鬓，愁绝独驱车。"]},{"t":"天津遇只都尉秉忠","f":"五言律诗","c":["匹马西京路，风尘遇冠军。","姓奇希见世，名美不忘君。","邀笛关山月，登楼海岱云。","相看头尚黑，塞下可邀勋。"]},{"t":"岁暮过淮阴","f":"五言律诗","c":["摇落出燕市，仓皇过楚城。","黄金随岁尽，白发待春生。","雪后鹑衣重，风前草笠轻。","几年悲命运，握粟问君平。"]},{"t":"渡江","f":"五言律诗","c":["十二月将尽，三千里外还。","船犹冲白浪，家已近青山。","暂罢穷途哭，难为故国颜。","解装无长物，朔雪处囊间。"]},{"t":"春游与谢都尉二首 其一","f":"五言律诗","c":["柳市裁春服，花郊费酒钱。","家贫不事事，行乐自年年。","黄鸟催提榼，青衣佐刺船。","未须投逆旅，芳草正堪眠。"]},{"t":"春游与谢都尉二首 其二","f":"五言律诗","c":["春草绿盈盈，飞英扑马轻。","秦楼临曲水，谢客是宣城。","柳弱丁年态，花娇子夜情。","升平无汗马，都护听流莺。"]},{"t":"滕村访姜太史二首 其一","f":"五言律诗","c":["逶迤桃李径，骀荡自阳春。","祭酒门如水，江干雨似尘。","苔生陶甓润，花发董帷新。","何事登封日，犹閒礼乐臣。"]},{"t":"滕村访姜太史二首 其二","f":"五言律诗","c":["玄亭耽寂寞，春雨碧氤氲。","竹净轩窗色，兰滋几席芬。","人伦郭有道，时命李将军。","莫便营东墅，苍生孰舍君。"]},{"t":"焦山旸公房二首 其一","f":"五言律诗","c":["孤绝江之岛，栖迟隐矣身。","迷花翚似绮，在藻鲚如银。","高枕流云覆，清言白日沦。","山中许玄度，支遁好为邻。"]},{"t":"焦山旸公房二首 其二","f":"五言律诗","c":["山径缘苍渚，松寮掩翠微。","断崖犹鹤碣，三诏尚渔矶。","衣楚青荷叶，江明白板扉。","临流当洗耳，鸥鹭不惊飞。"]},{"t":"赠朱别驾","f":"五言律诗","c":["毖慎曾无匹，西京石建如。","每移青玉案，恭展紫泥书。","善政遗三辅，浮名谢二疏。","通家能畜我，早晚侍安车。"]},{"t":"答许主簿","f":"五言律诗","c":["马曹一主簿，七十尚栖迟。","簪笔推先辈，悬车怅后期。","倾交霍去病，仰给郑当时。","年少余官薄，何然动尔思。"]},{"t":"子夜","f":"五言律诗","c":["花柳发韶年，妆成子夜妍。","弄箫成艳曲，调瑟岂哀弦。","翡翠巢金埒，鸳鸯扑锦缠。","不将银烛灭，看取玉人怜。"]},{"t":"骝马","f":"五言律诗","c":["紫骝元异种，剪拂倍光辉。","但遣衔金勒，何知有铁衣。","骄嘶承顾盼，踠足恋芳菲。","笑杀征西骑，沙场百战归。"]},{"t":"吴氏园寓二首 其一","f":"五言律诗","c":["落落燕山路，劳劳楚客身。","莫寻弹铗伴，且作灌园人。","白眼谁堪傲，青樽自慰贫。","桃源今负郭，借住岂缘秦。"]},{"t":"吴氏园寓二首 其二","f":"五言律诗","c":["高柳拂清池，名花开自迟。","染猩山踯躅，堆雪野酴醾。","亭子留行李，园丁烹伏雌。","再听浑不厌，隔水啭黄鹂。"]},{"t":"赠钱功甫二首 其一","f":"五言律诗","c":["潦倒经生业，凄凉国士心。","愁容非酒病，憨态为书淫。","再刖荆人璧，空悬燕市金。","魏其宾客尽，怪尔独相寻。"]},{"t":"赠钱功甫二首 其二","f":"五言律诗","c":["薄宦唯吾拙，诸生尔独贫。","他年文苑传，今日士林人。","蚀字真如蠹，牵衣故作鹑。","未须嗟濩落，晚贵最平津。"]},{"t":"归客","f":"五言律诗","c":["寂寞丘园卧，休论战胜肥。","云英流几席，山翠湿裳衣。","梅福辞人役，桐江有客归。","海鸥飞且止，相对已忘机。"]},{"t":"徐园","f":"五言律诗","c":["绿径依山转，朱楼抱水斜。","台前五松树，云里九莲花。","缥缈疑仙馆，玲珑象主家。","金昌亭下路，标起赤城霞。"]}]};